-- Full SPARK subject source-bank V2 staging: structural drafts, never final grading authority.
-- English A optional literary choices are separate 120-mark selections.
-- Integrated Science fixed combinations are previews, not randomly assembled learner papers.
begin;
insert into spark_grading_private.rubrics_v2(subject_id,rubric_version,paper_id,criteria,active,verification_status)
values ('mathematics','source-scheme-draft-v2','original-v1','[{"id":"p2-q1-v1::a","maxMarks":3,"sourcePartId":"p2-q1-v1::a","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"7","solution":"(2 1/3 + 1 3/4) = 7/3 + 7/4 = 28/12 + 21/12 = 49/12. (5/6 - 1/4) = 5/6 - 1/4 = 10/12 - 3/12 = 7/12. Dividing by a fraction means multiplying by its reciprocal, so 49/12 ÷ 7/12 = 49/12 × 12/7 = 7.","criteria":null}},{"id":"p2-q1-v1::b1","maxMarks":2,"sourcePartId":"p2-q1-v1::b1","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"3600.00","solution":"The selling price is 125% of the cost price, so cost = 4,500 × 100/125 = $3600.00.","criteria":null}},{"id":"p2-q1-v1::b2","maxMarks":2,"sourcePartId":"p2-q1-v1::b2","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"5040.00","solution":"New selling price = 3600.00 × 140/100 = $5040.00.","criteria":null}},{"id":"p2-q1-v1::b3","maxMarks":2,"sourcePartId":"p2-q1-v1::b3","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"12","solution":"Increase = 5040.00 - 4,500 = $540.00. As a percentage of the original selling price this is (540.00 ÷ 4,500) × 100 = 12%.","criteria":null}},{"id":"p2-q2-v1::a","maxMarks":2,"sourcePartId":"p2-q2-v1::a","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"2xy^3","solution":"Multiply the numerator: 12x^5y^5. Dividing, subtract the indices: 2xy^3.","criteria":null}},{"id":"p2-q2-v1::b1","maxMarks":2,"sourcePartId":"p2-q2-v1::b1","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"4(m - 5n)(m + 5n)","solution":"Take out the common factor 4: 4(m^2 - 25n^2). The bracket is a difference of two squares, so the answer is 4(m - 5n)(m + 5n).","criteria":null}},{"id":"p2-q2-v1::b2","maxMarks":2,"sourcePartId":"p2-q2-v1::b2","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"(2x - 3)(x + 4)","solution":"Split the middle term using 8 and 3: 2x^2 + 8x - 3x - 12 = 2x(x + 4) - 3(x + 4) = (2x - 3)(x + 4).","criteria":null}},{"id":"p2-q2-v1::c1","maxMarks":1,"sourcePartId":"p2-q2-v1::c1","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"8w + 8","solution":"Length = 3w + 4. Perimeter = 2[w + (3w + 4)] = 8w + 8.","criteria":null}},{"id":"p2-q2-v1::c2","maxMarks":2,"sourcePartId":"p2-q2-v1::c2","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"width 4.5 cm, length 17.5 cm","solution":"8w + 8 = 44, so 8w = 36 and w = 4.5. Width = 4.5 cm and length = 3(4.5) + 4 = 17.5 cm.","criteria":null}},{"id":"p2-q3-v1::a","maxMarks":3,"sourcePartId":"p2-q3-v1::a","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"A reflection in the x-axis (y = 0)","solution":"Each vertex keeps one coordinate and the other changes sign: (1, 1) maps to (1, -1), (5, 1) to (5, -1) and (1, 4) to (1, -4). That is a reflection in the x-axis.","criteria":null}},{"id":"p2-q3-v1::b","maxMarks":2,"sourcePartId":"p2-q3-v1::b","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"(-5, 3); (-1, 3); (-5, 6)","solution":"Add the translation vector to each vertex: (1, 1) + (-6, 2) = (-5, 3); (5, 1) + (-6, 2) = (-1, 3); (1, 4) + (-6, 2) = (-5, 6).","criteria":[]}},{"id":"p2-q3-v1::c","maxMarks":2,"sourcePartId":"p2-q3-v1::c","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"5.00","solution":"Length = sqrt[(1 - 5)^2 + (4 - 1)^2] = sqrt(25) = 5.00 units.","criteria":[]}},{"id":"p2-q3-v1::d","maxMarks":2,"sourcePartId":"p2-q3-v1::d","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"5.00 cm, because a reflection does not change the length of a line segment","solution":"A reflection is an isometry: it preserves length. The image of BC is therefore the same length as BC, 5.00 cm.","criteria":[{"kind":"B","code":"B1","marks":1,"field":"answer","depends":[],"profile":"conceptual","description":"states the length as 5.00 cm","check":{"type":"labelledValue","label":"","value":5,"index":0,"tolerance":0.011}},{"kind":"B","code":"B2","marks":1,"field":"answer","depends":[],"profile":"reasoning","description":"gives length preservation under reflection as the reason","check":{"type":"anyOf","options":[{"type":"prose","key":"a reflection does not change the length","tokens":["reflection","length","change"],"mustHave":["length"],"forbid":["enlargement"],"polarity":"negative","quorum":0.34},{"type":"prose","key":"the length stays the same under a reflection","tokens":["reflection","length","same","equal","congruent","unchanged","preserve","preserved","preserves","stays"],"mustHave":["length"],"forbid":["enlargement"],"polarity":"positive","quorum":0.2}]}}]}},{"id":"p2-q4-v1::a1","maxMarks":1,"sourcePartId":"p2-q4-v1::a1","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"15","solution":"f(4) = 2(4) + 7 = 15.","criteria":null}},{"id":"p2-q4-v1::a2","maxMarks":2,"sourcePartId":"p2-q4-v1::a2","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"9","solution":"Apply g first: g(2) = 2^2 - 3 = 1. Then f(1) = 2(1) + 7 = 9.","criteria":[]}},{"id":"p2-q4-v1::b","maxMarks":2,"sourcePartId":"p2-q4-v1::b","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"(x - 7)/2","solution":"Let y = 2x + 7. Interchanging the variables, x = 2y + 7, so 2y = x - 7 and y = (x - 7)/2. Check: f^-1(f(1)) = 1.","criteria":[]}},{"id":"p2-q4-v1::c","maxMarks":2,"sourcePartId":"p2-q4-v1::c","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"4 and -4","solution":"x^2 - 3 = 13, so x^2 = 16 and x = +/-4. The two values are 4 and -4.","criteria":null}},{"id":"p2-q4-v1::d","maxMarks":2,"sourcePartId":"p2-q4-v1::d","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"No, g does not have an inverse function, because g is many-to-one: two different values of x give the same value of g(x)","solution":"Part (c) shows that x = 4 and x = -4 both give g(x) = 13. A function has an inverse only when it is one-to-one, and g is many-to-one, so no inverse function exists.","criteria":[{"kind":"B","code":"B1","marks":1,"field":"answer","depends":[],"profile":"reasoning","description":"states that g has no inverse function","check":{"type":"prose","key":"g does not have an inverse function","tokens":["inverse"],"mustHave":["inverse"],"forbid":[],"polarity":"negative","quorum":0.5}},{"kind":"B","code":"B2","marks":1,"field":"answer","depends":[],"profile":"reasoning","description":"gives many-to-one as the reason","check":{"type":"prose","key":"because two values of x give the same value, so it is many-to-one","tokens":["many-to-one","two","same","value"],"mustHave":[],"forbid":["one-to-one"],"polarity":"positive","quorum":0.25}}]}},{"id":"p2-q5-v1::a","maxMarks":1,"sourcePartId":"p2-q5-v1::a","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"16 - 20","solution":"The class 16 - 20 has the highest frequency, 16.","criteria":null}},{"id":"p2-q5-v1::b","maxMarks":3,"sourcePartId":"p2-q5-v1::b","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"13","solution":"Use the class midpoints 3, 8, 13, 18. Sum of fx = 4(3) + 8(8) + 12(13) + 16(18) = 520. Mean = 520 / 40 = 13 kg.","criteria":null}},{"id":"p2-q5-v1::c","maxMarks":3,"sourcePartId":"p2-q5-v1::c","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"4, 12, 24, 40","solution":"Add the frequencies in order: 4, 12, 24, 40.","criteria":null}},{"id":"p2-q5-v1::d","maxMarks":2,"sourcePartId":"p2-q5-v1::d","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"2/5","solution":"16 of the 40 parcels have a mass greater than 15 kg, so the probability is 16/40 = 2/5.","criteria":null}},{"id":"p2-q6-v1::a","maxMarks":2,"sourcePartId":"p2-q6-v1::a","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"38.5","solution":"Area = πr^2 = (22/7)(3.5)^2 = 38.5 m^2.","criteria":null}},{"id":"p2-q6-v1::b","maxMarks":3,"sourcePartId":"p2-q6-v1::b","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"154","solution":"Volume = πr^2h = 38.5 × 4 = 154 m^3.","criteria":null}},{"id":"p2-q6-v1::c","maxMarks":2,"sourcePartId":"p2-q6-v1::c","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"88","solution":"Curved surface area = 2πrh = 2 × (22/7) × 3.5 × 4 = 88 m^2.","criteria":null}},{"id":"p2-q6-v1::d","maxMarks":2,"sourcePartId":"p2-q6-v1::d","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"28","solution":"Time = volume / rate = 154 / 5.5 = 28 hours.","criteria":null}},{"id":"p2-q7-v1::a","maxMarks":2,"sourcePartId":"p2-q7-v1::a","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"16, 16, 32","solution":"Design 4 has a 4 by 4 block, so 16 shaded tiles, and 4 unshaded tiles against each of the 4 sides, so 16 unshaded. The total is 32.","criteria":null}},{"id":"p2-q7-v1::b","maxMarks":4,"sourcePartId":"p2-q7-v1::b","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"shaded n^2; unshaded 4n; total n^2 + 4n","solution":"The shaded tiles form an n by n block, so there are n^2 of them. There are n unshaded tiles against each of the four sides, so 4n of them. The total is n^2 + 4n, which can also be written n(n + 4). Check with n = 3: 9 + 12 = 21, which matches the table.","criteria":null}},{"id":"p2-q7-v1::c","maxMarks":2,"sourcePartId":"p2-q7-v1::c","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"11","solution":"n^2 + 4n = 165, so n^2 + 4n - 165 = 0. Factorising gives (n + 15)(n - 11) = 0, so n = 11, since a design number must be positive. Check: 11^2 + 4(11) = 165.","criteria":null}},{"id":"p2-q7-v1::d","maxMarks":2,"sourcePartId":"p2-q7-v1::d","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"48","solution":"n^2 = 144, so n = 12. The number of unshaded tiles is 4n = 4(12) = 48.","criteria":null}},{"id":"p2-q8-v1::a","maxMarks":4,"sourcePartId":"p2-q8-v1::a","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"3(x - 2)^2 + 8","solution":"Take out the factor 3 from the first two terms: 3(x^2 - 4x) + 20. Completing the square inside the bracket, x^2 - 4x = (x - 2)^2 - 4. So f(x) = 3(x - 2)^2 + 8.","criteria":null}},{"id":"p2-q8-v1::b1","maxMarks":2,"sourcePartId":"p2-q8-v1::b1","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"8","solution":"3(x - 2)^2 is never negative and is zero when x = 2, so the least value of f(x) is 8.","criteria":null}},{"id":"p2-q8-v1::b2","maxMarks":2,"sourcePartId":"p2-q8-v1::b2","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"2","solution":"The square is zero when x - 2 = 0, that is x = 2.","criteria":null}},{"id":"p2-q8-v1::c","maxMarks":2,"sourcePartId":"p2-q8-v1::c","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"x = 2","solution":"The graph is symmetrical about the vertical line through the turning point, so the axis of symmetry is x = 2.","criteria":null}},{"id":"p2-q8-v1::d","maxMarks":2,"sourcePartId":"p2-q8-v1::d","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"(0, 20)","solution":"When x = 0, f(0) = 20, so the graph cuts the y-axis at (0, 20).","criteria":null}},{"id":"p2-q9-v1::a1","maxMarks":3,"sourcePartId":"p2-q9-v1::a1","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"52 degrees, because the angle at the centre is twice the angle at the circumference when both stand on the same arc AB","solution":"The angle at the centre is twice the angle at the circumference standing on the same arc AB, so x = 104 / 2 = 52.","criteria":null}},{"id":"p2-q9-v1::a2","maxMarks":2,"sourcePartId":"p2-q9-v1::a2","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"38","solution":"OA = OB because both are radii, so triangle OAB is isosceles and angle OAB = angle OBA. The angle sum gives angle OAB = (180 - 104) / 2 = 38°.","criteria":null}},{"id":"p2-q9-v1::b1","maxMarks":3,"sourcePartId":"p2-q9-v1::b1","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"Angle PQR = 90°","solution":"The bearing of P from Q is the back bearing of 40 degrees, that is 40 + 180 = 220 degrees. The bearing of R from Q is 130 degrees. Angle PQR is the angle between them at Q, so angle PQR = 220 - 130 = 90 degrees.","criteria":[{"kind":"M","code":"M1","marks":1,"field":"working","depends":[],"profile":"algorithmic","description":"finds the bearing of P from Q as 220 degrees","check":{"type":"reachesValue","values":[220],"relTolerance":0.000001}},{"kind":"M","code":"M2","marks":1,"field":"working","depends":["M1"],"profile":"algorithmic","description":"subtracts the two bearings at Q","check":{"type":"reachesValue","values":[130],"relTolerance":0.000001}},{"kind":"A","code":"A1","marks":1,"field":"all","depends":["M2"],"strictDepends":true,"profile":"reasoning","description":"concludes that angle PQR is 90 degrees","check":{"type":"containsValue","value":90,"tolerance":0.000001}}]}},{"id":"p2-q9-v1::b2","maxMarks":2,"sourcePartId":"p2-q9-v1::b2","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"150","solution":"Triangle PQR is right-angled at Q, so PR^2 = 90^2 + 120^2 = 22500 and PR = 150 km.","criteria":null}},{"id":"p2-q9-v1::b3","maxMarks":2,"sourcePartId":"p2-q9-v1::b3","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"093","solution":"tan(angle QPR) = 120/90, so angle QPR = 53.1°. The bearing of R from P is 40 + 53.1 = 93.1°, which is 093° to the nearest degree.","criteria":null}},{"id":"p2-q10-v1::a","maxMarks":3,"sourcePartId":"p2-q10-v1::a","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"[[8, 4], [4, 9]]","solution":"Pair each row of M with each column of N: entry (1,1) = 2(4) + 3(0) = 8; entry (1,2) = 2(-1) + 3(2) = 4; entry (2,1) = 1(4) + 5(0) = 4; entry (2,2) = 1(-1) + 5(2) = 9.","criteria":null}},{"id":"p2-q10-v1::b","maxMarks":1,"sourcePartId":"p2-q10-v1::b","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"7","solution":"det M = (2)(5) - (3)(1) = 10 - 3 = 7.","criteria":[]}},{"id":"p2-q10-v1::b2","maxMarks":1,"sourcePartId":"p2-q10-v1::b2","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"M is not singular, because its determinant is not zero","solution":"A matrix is singular when its determinant is zero, because only then does it fail to have an inverse. The determinant of M is 7, which is not zero, so M is not singular.","criteria":[{"kind":"B","code":"B1","marks":1,"field":"answer","depends":[],"profile":"reasoning","description":"says M is not singular because the determinant is not zero","check":{"type":"prose","key":"not singular because the determinant is not zero","tokens":["singular","determinant","zero","0"],"mustHave":[],"forbid":[],"polarity":"negative","quorum":0.34}}]}},{"id":"p2-q10-v1::c","maxMarks":3,"sourcePartId":"p2-q10-v1::c","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"(1/7)[[5, -3], [-1, 2]]","solution":"Interchange the entries on the leading diagonal and change the sign of the other two, then divide by the determinant: M^-1 = (1/7)[[5, -3], [-1, 2]]. Check: M × M^-1 gives the identity matrix.","criteria":null}},{"id":"p2-q10-v1::d","maxMarks":4,"sourcePartId":"p2-q10-v1::d","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"x = 2, y = 3","solution":"The system is M(x, y) = (13, 17), so (x, y) = M^-1(13, 17) = (1/7)(5(13) + (-3)(17), (-1)(13) + 2(17)) = (1/7)(14, 21), giving x = 2 and y = 3. Check: 2(2) + 3(3) = 13.","criteria":null}}]'::jsonb,false,'draft')
on conflict(subject_id,rubric_version,paper_id) do nothing;
insert into spark_grading_private.rubrics_v2(subject_id,rubric_version,paper_id,criteria,active,verification_status)
values ('mathematics','source-scheme-draft-v2','original-v2','[{"id":"p2-q1-v2::a","maxMarks":3,"sourcePartId":"p2-q1-v2::a","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"9/5","solution":"(3 1/5 - 1 7/10) = 16/5 - 17/10 = 32/10 - 17/10 = 3/2. (2/3 + 1/6) = 2/3 + 1/6 = 4/6 + 1/6 = 5/6. Dividing by a fraction means multiplying by its reciprocal, so 3/2 ÷ 5/6 = 3/2 × 6/5 = 9/5. As a mixed number this is 1 4/5.","criteria":null}},{"id":"p2-q1-v2::b1","maxMarks":2,"sourcePartId":"p2-q1-v2::b1","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"4500.00","solution":"The selling price is 120% of the cost price, so cost = 5,400 × 100/120 = $4500.00.","criteria":null}},{"id":"p2-q1-v2::b2","maxMarks":2,"sourcePartId":"p2-q1-v2::b2","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"6075.00","solution":"New selling price = 4500.00 × 135/100 = $6075.00.","criteria":null}},{"id":"p2-q1-v2::b3","maxMarks":2,"sourcePartId":"p2-q1-v2::b3","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"12.5","solution":"Increase = 6075.00 - 5,400 = $675.00. As a percentage of the original selling price this is (675.00 ÷ 5,400) × 100 = 12.5%.","criteria":null}},{"id":"p2-q2-v2::a","maxMarks":2,"sourcePartId":"p2-q2-v2::a","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"3x^2y^2","solution":"Multiply the numerator: 15x^5y^5. Dividing, subtract the indices: 3x^2y^2.","criteria":null}},{"id":"p2-q2-v2::b1","maxMarks":2,"sourcePartId":"p2-q2-v2::b1","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"3(m - 7n)(m + 7n)","solution":"Take out the common factor 3: 3(m^2 - 49n^2). The bracket is a difference of two squares, so the answer is 3(m - 7n)(m + 7n).","criteria":null}},{"id":"p2-q2-v2::b2","maxMarks":2,"sourcePartId":"p2-q2-v2::b2","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"(3x - 2)(x + 3)","solution":"Split the middle term using 9 and 2: 3x^2 + 9x - 2x - 6 = 3x(x + 3) - 2(x + 3) = (3x - 2)(x + 3).","criteria":null}},{"id":"p2-q2-v2::c1","maxMarks":1,"sourcePartId":"p2-q2-v2::c1","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"6w + 10","solution":"Length = 2w + 5. Perimeter = 2[w + (2w + 5)] = 6w + 10.","criteria":null}},{"id":"p2-q2-v2::c2","maxMarks":2,"sourcePartId":"p2-q2-v2::c2","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"width 6 cm, length 17 cm","solution":"6w + 10 = 46, so 6w = 36 and w = 6. Width = 6 cm and length = 2(6) + 5 = 17 cm.","criteria":null}},{"id":"p2-q3-v2::a","maxMarks":3,"sourcePartId":"p2-q3-v2::a","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"A reflection in the y-axis (x = 0)","solution":"Each vertex keeps one coordinate and the other changes sign: (2, 2) maps to (-2, 2), (6, 2) to (-6, 2) and (2, 5) to (-2, 5). That is a reflection in the y-axis.","criteria":null}},{"id":"p2-q3-v2::b","maxMarks":3,"sourcePartId":"p2-q3-v2::b","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"(5, -5); (9, -5); (5, -2)","solution":"Add the translation vector to each vertex: (2, 2) + (3, -7) = (5, -5); (6, 2) + (3, -7) = (9, -5); (2, 5) + (3, -7) = (5, -2).","criteria":null}},{"id":"p2-q3-v2::c","maxMarks":3,"sourcePartId":"p2-q3-v2::c","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"5.00","solution":"Length = sqrt[(2 - 6)^2 + (5 - 2)^2] = sqrt(25) = 5.00 units.","criteria":null}},{"id":"p2-q4-v2::a1","maxMarks":1,"sourcePartId":"p2-q4-v2::a1","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"13","solution":"f(6) = 3(6) - 5 = 13.","criteria":null}},{"id":"p2-q4-v2::a2","maxMarks":3,"sourcePartId":"p2-q4-v2::a2","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"25","solution":"Apply g first: g(3) = 3^2 + 1 = 10. Then f(10) = 3(10) - 5 = 25.","criteria":null}},{"id":"p2-q4-v2::b","maxMarks":3,"sourcePartId":"p2-q4-v2::b","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"(x + 5)/3","solution":"Let y = 3x - 5. Interchanging the variables, x = 3y - 5, so 3y = x + 5 and y = (x + 5)/3. Check: f^-1(f(1)) = 1.","criteria":null}},{"id":"p2-q4-v2::c","maxMarks":2,"sourcePartId":"p2-q4-v2::c","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"5 and -5","solution":"x^2 + 1 = 26, so x^2 = 25 and x = +/-5. The two values are 5 and -5.","criteria":null}},{"id":"p2-q5-v2::a","maxMarks":1,"sourcePartId":"p2-q5-v2::a","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"11 - 15","solution":"The class 11 - 15 has the highest frequency, 12.","criteria":null}},{"id":"p2-q5-v2::b","maxMarks":3,"sourcePartId":"p2-q5-v2::b","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"13","solution":"Use the class midpoints 3, 8, 13, 18, 23. Sum of fx = 5(3) + 9(8) + 12(13) + 9(18) + 5(23) = 520. Mean = 520 / 40 = 13 kg.","criteria":null}},{"id":"p2-q5-v2::c","maxMarks":3,"sourcePartId":"p2-q5-v2::c","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"5, 14, 26, 35, 40","solution":"Add the frequencies in order: 5, 14, 26, 35, 40.","criteria":null}},{"id":"p2-q5-v2::d","maxMarks":2,"sourcePartId":"p2-q5-v2::d","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"7/20","solution":"14 of the 40 parcels have a mass greater than 15 kg, so the probability is 14/40 = 7/20.","criteria":null}},{"id":"p2-q6-v2::a","maxMarks":2,"sourcePartId":"p2-q6-v2::a","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"154","solution":"Area = πr^2 = (22/7)(7)^2 = 154 m^2.","criteria":null}},{"id":"p2-q6-v2::b","maxMarks":3,"sourcePartId":"p2-q6-v2::b","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"2310","solution":"Volume = πr^2h = 154 × 15 = 2310 m^3.","criteria":null}},{"id":"p2-q6-v2::c","maxMarks":2,"sourcePartId":"p2-q6-v2::c","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"660","solution":"Curved surface area = 2πrh = 2 × (22/7) × 7 × 15 = 660 m^2.","criteria":null}},{"id":"p2-q6-v2::d","maxMarks":2,"sourcePartId":"p2-q6-v2::d","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"110","solution":"Time = volume / rate = 2310 / 21 = 110 hours.","criteria":null}},{"id":"p2-q7-v2::a","maxMarks":2,"sourcePartId":"p2-q7-v2::a","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"16, 16, 32","solution":"Design 4 has a 4 by 4 block, so 16 shaded tiles, and 4 unshaded tiles against each of the 4 sides, so 16 unshaded. The total is 32.","criteria":null}},{"id":"p2-q7-v2::b","maxMarks":4,"sourcePartId":"p2-q7-v2::b","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"shaded n^2; unshaded 4n; total n^2 + 4n","solution":"The shaded tiles form an n by n block, so there are n^2 of them. There are n unshaded tiles against each of the four sides, so 4n of them. The total is n^2 + 4n, which can also be written n(n + 4). Check with n = 3: 9 + 12 = 21, which matches the table.","criteria":null}},{"id":"p2-q7-v2::c","maxMarks":2,"sourcePartId":"p2-q7-v2::c","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"8","solution":"n^2 + 4n = 96, so n^2 + 4n - 96 = 0. Factorising gives (n + 12)(n - 8) = 0, so n = 8, since a design number must be positive. Check: 8^2 + 4(8) = 96.","criteria":null}},{"id":"p2-q7-v2::d","maxMarks":2,"sourcePartId":"p2-q7-v2::d","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"60","solution":"n^2 = 225, so n = 15. The number of unshaded tiles is 4n = 4(15) = 60.","criteria":null}},{"id":"p2-q8-v2::a","maxMarks":4,"sourcePartId":"p2-q8-v2::a","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"2(x + 3)^2 + 5","solution":"Take out the factor 2 from the first two terms: 2(x^2 + 6x) + 23. Completing the square inside the bracket, x^2 + 6x = (x + 3)^2 - 9. So f(x) = 2(x + 3)^2 + 5.","criteria":null}},{"id":"p2-q8-v2::b1","maxMarks":2,"sourcePartId":"p2-q8-v2::b1","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"5","solution":"2(x + 3)^2 is never negative and is zero when x = -3, so the least value of f(x) is 5.","criteria":null}},{"id":"p2-q8-v2::b2","maxMarks":2,"sourcePartId":"p2-q8-v2::b2","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"-3","solution":"The square is zero when x + 3 = 0, that is x = -3.","criteria":null}},{"id":"p2-q8-v2::c","maxMarks":2,"sourcePartId":"p2-q8-v2::c","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"x = -3","solution":"The graph is symmetrical about the vertical line through the turning point, so the axis of symmetry is x = -3.","criteria":null}},{"id":"p2-q8-v2::d","maxMarks":2,"sourcePartId":"p2-q8-v2::d","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"(0, 23)","solution":"When x = 0, f(0) = 23, so the graph cuts the y-axis at (0, 23).","criteria":null}},{"id":"p2-q9-v2::a1","maxMarks":3,"sourcePartId":"p2-q9-v2::a1","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"64 degrees, because the angle at the centre is twice the angle at the circumference when both stand on the same arc AB","solution":"The angle at the centre is twice the angle at the circumference standing on the same arc AB, so x = 128 / 2 = 64.","criteria":null}},{"id":"p2-q9-v2::a2","maxMarks":2,"sourcePartId":"p2-q9-v2::a2","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"26","solution":"OA = OB because both are radii, so triangle OAB is isosceles and angle OAB = angle OBA. The angle sum gives angle OAB = (180 - 128) / 2 = 26°.","criteria":null}},{"id":"p2-q9-v2::b1","maxMarks":3,"sourcePartId":"p2-q9-v2::b1","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"Angle PQR = 90°","solution":"The bearing of P from Q is the back bearing of 55 degrees, that is 55 + 180 = 235 degrees. The bearing of R from Q is 145 degrees. Angle PQR is the angle between them at Q, so angle PQR = 235 - 145 = 90 degrees.","criteria":[{"kind":"M","code":"M1","marks":1,"field":"working","depends":[],"profile":"algorithmic","description":"finds the bearing of P from Q as 235 degrees","check":{"type":"reachesValue","values":[235],"relTolerance":0.000001}},{"kind":"M","code":"M2","marks":1,"field":"working","depends":["M1"],"profile":"algorithmic","description":"subtracts the two bearings at Q","check":{"type":"reachesValue","values":[145],"relTolerance":0.000001}},{"kind":"A","code":"A1","marks":1,"field":"all","depends":["M2"],"strictDepends":true,"profile":"reasoning","description":"concludes that angle PQR is 90 degrees","check":{"type":"containsValue","value":90,"tolerance":0.000001}}]}},{"id":"p2-q9-v2::b2","maxMarks":2,"sourcePartId":"p2-q9-v2::b2","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"100","solution":"Triangle PQR is right-angled at Q, so PR^2 = 60^2 + 80^2 = 10000 and PR = 100 km.","criteria":null}},{"id":"p2-q9-v2::b3","maxMarks":2,"sourcePartId":"p2-q9-v2::b3","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"108","solution":"tan(angle QPR) = 80/60, so angle QPR = 53.1°. The bearing of R from P is 55 + 53.1 = 108.1°, which is 108° to the nearest degree.","criteria":null}},{"id":"p2-q10-v2::a","maxMarks":3,"sourcePartId":"p2-q10-v2::a","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"[[3, -1], [2, 16]]","solution":"Pair each row of M with each column of N: entry (1,1) = 3(1) + 1(0) = 3; entry (1,2) = 3(-2) + 1(5) = -1; entry (2,1) = 2(1) + 4(0) = 2; entry (2,2) = 2(-2) + 4(5) = 16.","criteria":null}},{"id":"p2-q10-v2::b","maxMarks":2,"sourcePartId":"p2-q10-v2::b","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"10","solution":"det M = (3)(4) - (1)(2) = 12 - 2 = 10.","criteria":null}},{"id":"p2-q10-v2::c","maxMarks":3,"sourcePartId":"p2-q10-v2::c","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"(1/10)[[4, -1], [-2, 3]]","solution":"Interchange the entries on the leading diagonal and change the sign of the other two, then divide by the determinant: M^-1 = (1/10)[[4, -1], [-2, 3]]. Check: M × M^-1 gives the identity matrix.","criteria":null}},{"id":"p2-q10-v2::d","maxMarks":4,"sourcePartId":"p2-q10-v2::d","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"x = 2, y = 5","solution":"The system is M(x, y) = (11, 24), so (x, y) = M^-1(11, 24) = (1/10)(4(11) + (-1)(24), (-2)(11) + 3(24)) = (1/10)(20, 50), giving x = 2 and y = 5. Check: 3(2) + 1(5) = 11.","criteria":null}}]'::jsonb,false,'draft')
