insert into spark_grading_private.rubrics_v2(subject_id,rubric_version,paper_id,criteria,active,verification_status)
values ('mathematics','source-scheme-draft-v2','p2e','[{"id":"p2e-q1::a","maxMarks":3,"sourcePartId":"p2e-q1::a","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"86/13","solution":"2 3/4 = 11/4, so the numerator is 11/4 + 5/6 = 43/12. The denominator is 7/8 - 1/3 = 13/24. Dividing means multiplying by the reciprocal: 43/12 x 24/13 = 86/13.","criteria":[{"kind":"M","marks":1,"description":"writes the numerator as a single fraction","check":{"type":"contains","value":[3.5833333333333335]},"field":"all","code":"M1"},{"kind":"M","marks":1,"description":"writes the denominator as a single fraction","check":{"type":"contains","value":[0.5416666666666666]},"field":"all","code":"M2"},{"kind":"A","marks":1,"description":"the exact value in its lowest terms","check":{"type":"fraction","value":6.615384615384615,"simplified":true,"requireFraction":true},"field":"answer","code":"A1","depends":["M2"]}]}},{"id":"p2e-q1::b1","maxMarks":2,"sourcePartId":"p2e-q1::b1","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"4080.00","solution":"The discount is 15% of $4,800 = $720.00. The cash price is $4,800 - $720.00 = $4,080.00.","criteria":[{"kind":"M","marks":1,"description":"finds 15% of $4,800","check":{"type":"contains","value":[720]},"field":"all","code":"M1"},{"kind":"A","marks":1,"description":"the cash price","check":{"type":"numeric","value":4080,"dp":2,"tolerance":0.011},"field":"answer","code":"A1","depends":["M1"]}]}},{"id":"p2e-q1::b2","maxMarks":2,"sourcePartId":"p2e-q1::b2","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"4590.00","solution":"VAT = 12.5% of $4,080.00 = $510.00. The customer pays $4,080.00 + $510.00 = $4,590.00.","criteria":[{"kind":"M","marks":1,"description":"finds 12.5% of the cash price","check":{"type":"contains","value":[510]},"field":"all","code":"M1"},{"kind":"A","marks":1,"description":"the amount paid","check":{"type":"numeric","value":4590,"dp":2,"tolerance":0.011},"field":"answer","ecf":{"uses":["b1"],"formula":"b1 * 1.125"},"code":"A1","depends":["M1"]}]}},{"id":"p2e-q1::c","maxMarks":2,"sourcePartId":"p2e-q1::c","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"930.00","solution":"The hire purchase price is $900 + 12 x $385 = $900 + $4,620 = $5,520.00. That is $5,520.00 - $4,590.00 = $930.00 more.","criteria":[{"kind":"M","marks":1,"description":"finds the total hire purchase price","check":{"type":"contains","value":[5520]},"field":"all","code":"M1"},{"kind":"A","marks":1,"description":"the extra amount paid","check":{"type":"numeric","value":930,"dp":2,"tolerance":0.011},"field":"answer","ecf":{"uses":["b2"],"formula":"5520.0 - b2"},"code":"A1","depends":["M1"]}]}},{"id":"p2e-q2::a","maxMarks":2,"sourcePartId":"p2e-q2::a","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"26","solution":"Substituting a = 4 and b = -2: the numerator is 3(4)^2 - 2(-2) = 48 + 4 = 52, and the denominator is (4) + (-2) = 4 - 2 = 2. So T = 52/2 = 26.","criteria":[{"kind":"M","marks":1,"description":"substitutes a = 4 and b = -2 into the formula","check":{"type":"contains","value":[4,-2]},"field":"all","code":"M1"},{"kind":"A","marks":1,"description":"the value of T","check":{"type":"numeric","value":26,"tolerance":0.000001},"field":"answer","code":"A1","depends":["M1"]}]}},{"id":"p2e-q2::b1","maxMarks":2,"sourcePartId":"p2e-q2::b1","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"2x^2 + 7x - 15","solution":"Multiplying each term in the first bracket by each term in the second: (2x - 3)(x + 5) = 2x^2 + 10x - 3x - 15. Collecting the two terms in x: 2x^2 + 7x - 15.","criteria":[{"kind":"M","marks":1,"description":"multiplies out to give the four products","check":{"type":"contains","value":[10,3]},"field":"all","code":"M1"},{"kind":"A","marks":1,"description":"the expansion in its simplest form","check":{"type":"expression","value":"2x^2 + 7x - 15","accepted":["2x^2 - 15 + 7x"]},"field":"answer","code":"A1","depends":["M1"]}]}},{"id":"p2e-q2::b2","maxMarks":2,"sourcePartId":"p2e-q2::b2","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"(2x - 5y)(2x + 5y)","solution":"4x^2 - 25y^2 is a difference of two squares: 4x^2 - 25y^2 = (2x)^2 - (5y)^2 = (2x - 5y)(2x + 5y).","criteria":[{"kind":"M","marks":1,"description":"recognises the difference of two squares","check":{"type":"method","any":["difference of two squares"]},"field":"all","code":"M1"},{"kind":"A","marks":1,"description":"the complete factorisation","check":{"type":"expression","value":"(2x - 5y)(2x + 5y)","accepted":["(2x + 5y)(2x - 5y)"],"requireFactorised":true},"field":"answer","code":"A1","depends":["M1"]}]}},{"id":"p2e-q2::c","maxMarks":2,"sourcePartId":"p2e-q2::c","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"x > 11/3; the smallest integer value of x is 4","solution":"5x - 3 > 2x + 8. Collecting the terms in x on one side and the numbers on the other: 3x > 11. Dividing both sides by 3: x > 11/3. Since 11/3 lies between 3 and 4, the smallest integer value of x that satisfies the inequality is 4.","criteria":[{"kind":"M","marks":1,"description":"collects the terms in x on one side","check":{"type":"contains","value":[3,11]},"field":"all","code":"M1"},{"kind":"A","marks":1,"description":"solves the inequality","check":{"type":"inequality","value":"x > 11/3"},"field":"all","code":"A1","depends":["M1"]},{"kind":"B","marks":0,"description":"states the smallest integer value of x","check":{"type":"numeric","value":4,"tolerance":0.000001},"field":"answer","depends":[],"code":"B1"}]}},{"id":"p2e-q2::d","maxMarks":1,"sourcePartId":"p2e-q2::d","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"At x = 11/3 the two sides are equal, and the inequality is strict, so it requires one side to be greater than the other","solution":"Substituting x = 11/3 makes 5x - 3 and 2x + 8 both equal to 46/3. The inequality is 5x - 3 > 2x + 8, a strict inequality, which is not satisfied when the two sides are equal.","criteria":[{"kind":"B","code":"B1","marks":1,"field":"answer","depends":[],"profile":"reasoning","description":"says the two sides are equal there and the inequality is strict","check":{"type":"prose","key":"the two sides are equal, and the inequality is strict rather than greater than or equal","tokens":["equal","strict","greater","sides"],"mustHave":["equal"],"forbid":[],"polarity":"positive","quorum":0.25}}]}},{"id":"p2e-q3::a","maxMarks":2,"sourcePartId":"p2e-q3::a","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"A(-4, -1) and B(2, 8) correctly plotted","solution":"A(-4, -1) is 4 units to the left of the y-axis and 1 unit below the x-axis. B(2, 8) is 2 units to the right of the y-axis and 8 units above the x-axis. Each point is marked where those two grid lines cross.","criteria":null}},{"id":"p2e-q3::b","maxMarks":2,"sourcePartId":"p2e-q3::b","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"(-1, 7/2)","solution":"The midpoint of AB is ((-4) + (2))/2 for the x-coordinate and ((-1) + (8))/2 for the y-coordinate. Now (-4) + (2) = -2 and (-1) + (8) = 7, so the midpoint of AB is (-1, 7/2).","criteria":[{"kind":"M","marks":1,"description":"adds the two x-coordinates and the two y-coordinates, and halves each sum","check":{"type":"anyOf","options":[{"type":"contains","value":[-2,7]},{"type":"coordinate","value":[-1,3.5],"tolerance":0.000001}]},"field":"all","code":"M1"},{"kind":"A","marks":1,"description":"the coordinates of the midpoint","check":{"type":"coordinate","value":[-1,3.5],"tolerance":0.000001},"field":"answer","code":"A1","depends":["M1"]}]}},{"id":"p2e-q3::c","maxMarks":2,"sourcePartId":"p2e-q3::c","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"3/2","solution":"The gradient of AB is (the change in y)/(the change in x). The change in y is (8) - (-1) = 9 and the change in x is (2) - (-4) = 6, so the gradient of AB is 9/6 = 3/2.","criteria":[{"kind":"M","marks":1,"description":"uses gradient = (y2 - y1)/(x2 - x1)","check":{"type":"anyOf","options":[{"type":"contains","value":[9,6]},{"type":"numeric","value":1.5,"tolerance":0.000001}]},"field":"all","code":"M1"},{"kind":"A","marks":1,"description":"the gradient of AB","check":{"type":"numeric","value":1.5,"tolerance":0.000001},"field":"answer","code":"A1","depends":["M1"]}]}},{"id":"p2e-q3::d","maxMarks":3,"sourcePartId":"p2e-q3::d","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"y = (3/2)x + 5","solution":"The gradient is m = 3/2. Substituting m = 3/2 and the point A(-4, -1) into y = mx + c gives (-1) = (3/2)(-4) + c, that is (-1) = -6 + c, so c = (-1) - (-6) = 5. The equation of the line AB is y = (3/2)x + 5.","criteria":[{"kind":"M","marks":1,"description":"substitutes the gradient and the coordinates of a point on the line into y = mx + c","check":{"type":"anyOf","options":[{"type":"method","any":["y = mx + c","substituting"]},{"type":"equation","value":"y = (3/2)x + 5"}]},"field":"all","code":"M1"},{"kind":"A","marks":1,"description":"the value of the intercept c","check":{"type":"contains","value":[5]},"field":"all","ecf":{"uses":["c"],"formula":"(-1) - c * (-4)"},"code":"A1","depends":["M1"]},{"kind":"A","marks":1,"description":"the equation of AB in the form y = mx + c","check":{"type":"equation","value":"y = (3/2)x + 5"},"field":"answer","code":"A2","depends":["M1"]}]}},{"id":"p2e-q4::a1","maxMarks":3,"sourcePartId":"p2e-q4::a1","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"triangle ABC with AB = 9 cm, BC = 6 cm and AC = 7 cm, with the arcs that locate C clearly shown","solution":"AB = 9 cm is given. Open the compasses to 7 cm; with centre A draw an arc above AB. Without changing the drawing, open the compasses to 6 cm; with centre B draw a second arc to cut the first at C. Join AC and BC with the ruler. The two arcs must be left on the page - they are the mark for the construction.","criteria":null}},{"id":"p2e-q4::a2","maxMarks":1,"sourcePartId":"p2e-q4::a2","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"22","solution":"The three sides are 9 cm, 6 cm and 7 cm, so the perimeter is 9 + 6 + 7 = 22 cm.","criteria":[{"kind":"B","marks":1,"description":"the perimeter of the triangle","check":{"type":"numeric","value":22,"tolerance":0.011},"field":"answer","depends":[],"code":"B1"}]}},{"id":"p2e-q4::b","maxMarks":2,"sourcePartId":"p2e-q4::b","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"51","solution":"Measuring angle ABC with a protractor gives 51°. (A check by the cosine rule: cos B = (9^2 + 6^2 - 7^2)/(2 x 9 x 6) = 68/108, so angle ABC = 51.0°.) A reading within 5° of that earns the first mark and a reading within 2° earns the second.","criteria":[{"kind":"B","marks":1,"description":"a reading within 5° of the correct value","check":{"type":"numeric","value":50.977197434767156,"tolerance":5.5},"field":"answer","depends":[],"code":"B1"},{"kind":"B","marks":1,"description":"the value correct to within 2°","check":{"type":"numeric","value":50.977197434767156,"tolerance":2.5},"field":"answer","depends":[],"code":"B2"}]}},{"id":"p2e-q4::b2","maxMarks":1,"sourcePartId":"p2e-q4::b2","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"Because 6^2 + 7^2 = 85, which is not equal to 9^2 = 81, so the converse of Pythagoras'' theorem does not hold","solution":"If the triangle were right-angled, the square on the longest side would equal the sum of the squares on the other two. Here 9^2 = 81 while 6^2 + 7^2 = 36 + 49 = 85. The two are not equal, so the triangle is not right-angled.","criteria":[{"kind":"B","code":"B1","marks":1,"field":"answer","depends":[],"profile":"reasoning","description":"compares the square on the longest side with the sum of the other two","check":{"type":"prose","key":"because 81 is not equal to 85, the squares do not add up, pythagoras","tokens":["81","85","square","pythagoras","equal"],"mustHave":[],"forbid":[],"polarity":"positive","quorum":0.25}}]}},{"id":"p2e-q4::c","maxMarks":2,"sourcePartId":"p2e-q4::c","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"117.25","solution":"Area of the rectangle = 14 x 7 = 98 cm^2. The semicircle has diameter 7 cm, so its radius is 3.5 cm. Area of the semicircle = (1/2) x π x r^2 = (1/2) x 22/7 x 3.5^2 = (1/2) x 22/7 x 12.25 = 19.25 cm^2. Total area = 98 + 19.25 = 117.25 cm^2.","criteria":[{"kind":"M","marks":1,"description":"finds the area of the rectangle","check":{"type":"contains","value":[98]},"field":"all","code":"M1"},{"kind":"A","marks":1,"description":"the total area of the figure","check":{"type":"numeric","value":117.25,"tolerance":0.011},"field":"answer","code":"A1","depends":["M2"]}]}},{"id":"p2e-q5::a","maxMarks":3,"sourcePartId":"p2e-q5::a","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"25.5, 35.5, 45.5; 357, 248.5, 136.5","solution":"The mid-interval value is the mean of the class boundaries, and f x is the frequency times that value: (21 + 30)/2 = 25.5, 14 x 25.5 = 357; (31 + 40)/2 = 35.5, 7 x 35.5 = 248.5; (41 + 50)/2 = 45.5, 3 x 45.5 = 136.5.","criteria":null}},{"id":"p2e-q5::b","maxMarks":1,"sourcePartId":"p2e-q5::b","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"21 - 30","solution":"The class 21 - 30 has the highest frequency, 14.","criteria":[{"kind":"B","marks":1,"description":"the modal class","check":{"type":"set","value":[21,30],"tolerance":0.000001},"field":"answer","depends":[],"code":"B1"}]}},{"id":"p2e-q5::c","maxMarks":3,"sourcePartId":"p2e-q5::c","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"23.3","solution":"Use the mid-interval values 5.5, 15.5, 25.5, 35.5, 45.5. The sum of f x is 33 + 155 + 357 + 248.5 + 136.5 = 930. The estimated mean is 930/40 = 23.3.","criteria":[{"kind":"M","marks":1,"description":"uses the mid-interval values","check":{"type":"contains","value":[45.5]},"field":"all","code":"M1"},{"kind":"M","marks":1,"description":"finds the sum of f x","check":{"type":"contains","value":[930]},"field":"all","code":"M2"},{"kind":"A","marks":1,"description":"the estimated mean","check":{"type":"numeric","value":23.25,"dp":1,"tolerance":0.06},"field":"answer","code":"A1","depends":["M2"]}]}},{"id":"p2e-q5::d","maxMarks":2,"sourcePartId":"p2e-q5::d","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"3/5","solution":"24 of the 40 values are at least 21, so the probability is 24/40 = 3/5.","criteria":[{"kind":"M","marks":1,"description":"finds how many are at least 21","check":{"type":"contains","value":[24]},"field":"all","code":"M1"},{"kind":"A","marks":1,"description":"the probability in its lowest terms","check":{"type":"fraction","value":0.6,"simplified":true,"requireFraction":true},"field":"answer","code":"A1","depends":["M1"]}]}},{"id":"p2e-q6::a","maxMarks":2,"sourcePartId":"p2e-q6::a","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"120","solution":"OA and OB are radii of the same circle, so OA = OB and triangle OAB is isosceles. Hence angle OBA = angle OAB = 30°. The angles of a triangle add up to 180°, so y = 180 - 30 - 30 = 120°.","criteria":[{"kind":"M","marks":1,"description":"uses OA = OB, so angle OBA = angle OAB","check":{"type":"method","any":["isosceles","radii","radius"]},"field":"all","code":"M1"},{"kind":"A","marks":1,"description":"the size of angle AOB","check":{"type":"numeric","value":120,"tolerance":0.011},"field":"answer","code":"A1","depends":["M1"]}]}},{"id":"p2e-q6::b","maxMarks":2,"sourcePartId":"p2e-q6::b","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"60","solution":"Angle AOB at the centre and angle ACB at the circumference both stand on the same arc AB. The angle at the centre is twice the angle at the circumference, so x = 120° / 2 = 60°.","criteria":[{"kind":"M","marks":1,"description":"uses the angle at the centre is twice the angle at the circumference","check":{"type":"method","any":["twice the angle at the circumference","angle at the centre"]},"field":"all","code":"M1"},{"kind":"A","marks":1,"description":"the size of angle ACB","check":{"type":"numeric","value":60,"tolerance":0.011},"field":"answer","ecf":{"uses":["a"],"formula":"a / 2"},"code":"A1","depends":["M1"]}]}},{"id":"p2e-q6::c","maxMarks":2,"sourcePartId":"p2e-q6::c","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"The angle at the centre is twice the angle at the circumference when both angles stand on the same arc AB, so angle ACB is half of angle AOB, giving x = 60 degrees.","solution":"Angle AOB and angle ACB both stand on the arc AB, one at the centre and one at the circumference. The theorem the angle at the centre is twice the angle at the circumference standing on the same arc gives angle ACB = 120° / 2 = 60°. Naming the theorem earns 1 mark and saying that the two angles stand on the same arc AB earns the second.","criteria":[{"kind":"B","marks":1,"description":"names the theorem: the angle at the centre is twice the angle at the circumference","check":{"type":"written","id":"theorem","description":"names the theorem: the angle at the centre is twice the angle at the circumference","any":["angle at the centre is twice the angle at the circumference","twice the angle at the circumference","centre is twice"]},"field":"answer","code":"B1"},{"kind":"B","marks":1,"description":"states that the two angles stand on the same arc","check":{"type":"written","id":"arc","description":"states that the two angles stand on the same arc","any":["same arc","same segment","arc ab"]},"field":"answer","code":"B2"}]}},{"id":"p2e-q6::d","maxMarks":3,"sourcePartId":"p2e-q6::d","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"462","solution":"The angle of the sector at the centre is 120°, so the sector is 120/360 = 1/3 of the circle. Area of sector = (120/360) x π x r^2 = (1/3) x (22/7) x 21^2 = (1/3) x (22/7) x 441 = 462 cm^2.","criteria":[{"kind":"M","marks":1,"description":"uses area of a sector = (angle/360) x pi x r^2","check":{"type":"method","any":["/360","sector"]},"field":"all","code":"M1"},{"kind":"M","marks":1,"description":"substitutes r = 21 and pi = 22/7","check":{"type":"contains","value":[441]},"field":"all","code":"M2"},{"kind":"A","marks":1,"description":"the area of the sector","check":{"type":"numeric","value":462,"tolerance":0.011},"field":"answer","ecf":{"uses":["a"],"formula":"a * 3.85"},"code":"A1","depends":["M2"]}]}},{"id":"p2e-q7::a","maxMarks":4,"sourcePartId":"p2e-q7::a","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"10, 15, 55, n(n + 1)/2","solution":"The number of dots in Figure n is n(n + 1)/2. Figure 4 has 10 dots and Figure 5 has 15 dots, each found by continuing the pattern or by using the rule. Figure 10 has 55 dots. In Figure n there are n(n + 1)/2 dots, which checks against the table: for n = 3 it gives 6.","criteria":null}},{"id":"p2e-q7::b","maxMarks":2,"sourcePartId":"p2e-q7::b","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"325","solution":"Using the rule n(n + 1)/2 from (a) with n = 25: (25 x 26)/2 = 650/2 = 325. So Figure 25 has 325 dots.","criteria":[{"kind":"M","marks":1,"description":"substitutes n = 25 into the rule for Figure n","check":{"type":"contains","value":[26]},"field":"all","code":"M1"},{"kind":"A","marks":1,"description":"the number of dots in Figure 25","check":{"type":"numeric","value":325,"tolerance":0.000001},"field":"answer","code":"A1","depends":["M1"]}]}},{"id":"p2e-q7::c","maxMarks":4,"sourcePartId":"p2e-q7::c","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"19","solution":"Set the rule equal to 190: n(n + 1)/2 = 190. Multiplying both sides by 2 gives n(n + 1) = 380, that is n^2 + n - 380 = 0. Factorising, (n + 20)(n - 19) = 0, so n = -20 or n = 19. A figure number must be a positive whole number, so the figure is Figure 19. Check: (19 x 20)/2 = 190.","criteria":[{"kind":"M","marks":1,"description":"writes the equation n(n + 1)/2 = 190","check":{"type":"contains","value":[190]},"field":"all","code":"M1"},{"kind":"M","marks":1,"description":"writes it as a quadratic equation equal to zero","check":{"type":"method","any":["n^2 + n - 380 = 0"]},"field":"all","code":"M2"},{"kind":"M","marks":1,"description":"solves the quadratic equation","check":{"type":"method","any":["(n + 20)(n - 19)","factoris","quadratic formula"]},"field":"all","code":"M3"},{"kind":"A","marks":1,"description":"the figure number, rejecting the negative root","check":{"type":"numeric","value":19,"tolerance":0.000001},"field":"answer","code":"A1","depends":["M3"]}]}},{"id":"p2e-q8::a","maxMarks":2,"sourcePartId":"p2e-q8::a","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"-3, -3","solution":"when x = 0, y = (0)^2 - 2(0) - 3 = -3; when x = 2, y = (2)^2 - 2(2) - 3 = -3.","criteria":null}},{"id":"p2e-q8::b","maxMarks":4,"sourcePartId":"p2e-q8::b","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"the points (-2, 5) to (4, 5) joined by a smooth curve","solution":"Plot the seven points from the table and join them with a single smooth curve. Do not join them with straight lines.","criteria":null}},{"id":"p2e-q8::c","maxMarks":2,"sourcePartId":"p2e-q8::c","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"(1, -4)","solution":"The curve turns at its lowest point, where x = 1 and y = -4. The minimum point is (1, -4).","criteria":[{"kind":"M","marks":1,"description":"identifies the turning point of the curve","check":{"type":"contains","value":[1]},"field":"all","code":"M1"},{"kind":"A","marks":1,"description":"the coordinates of the minimum","check":{"type":"coordinate","value":[1,-4],"tolerance":0.3},"field":"answer","code":"A1","depends":["M1"],"captureIndex":0}]}},{"id":"p2e-q8::d","maxMarks":2,"sourcePartId":"p2e-q8::d","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"x = -1 and x = 3","solution":"The curve crosses the x axis where y = 0, at x = -1 and x = 3.","criteria":[{"kind":"M","marks":1,"description":"reads where the curve crosses the x axis","check":{"type":"method","any":["x axis","y = 0","crosses"]},"field":"all","code":"M1"},{"kind":"A","marks":1,"description":"both values of x","check":{"type":"set","value":[-1,3],"tolerance":0.3},"field":"answer","code":"A1","depends":["M1"]}]}},{"id":"p2e-q8::e","maxMarks":2,"sourcePartId":"p2e-q8::e","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"x = 1","solution":"The axis of symmetry is the vertical line through the minimum point, so its equation is x = 1.","criteria":[{"kind":"M","marks":1,"description":"refers to the vertical line through the minimum","check":{"type":"method","any":["axis of symmetry","vertical","minimum"]},"field":"all","code":"M1"},{"kind":"A","marks":1,"description":"the equation of the axis of symmetry","check":{"type":"equation","value":"x = 1"},"field":"answer","ecf":{"uses":["c"],"formula":"c","template":"x = {v}"},"code":"A1","depends":["M1"]}]}},{"id":"p2e-q9::a","maxMarks":4,"sourcePartId":"p2e-q9::a","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"123.0","solution":"The bearing of P from Q is 78 + 180 = 258°, so angle PQR = 258 - 143 = 115°. By the cosine rule, PR^2 = PQ^2 + QR^2 - 2(PQ)(QR) cos PQR = 85^2 + 60^2 - 2(85)(60) cos 115° = 7225 + 3600 + 4310.7063 = 15135.7063. So PR = sqrt(15135.7063) = 123.0273 = 123.0 km, correct to 1 decimal place.","criteria":[{"kind":"M","marks":1,"description":"finds angle PQR = 115 degrees from the bearings","check":{"type":"contains","value":[115]},"field":"all","code":"M1"},{"kind":"M","marks":1,"description":"uses the cosine rule","check":{"type":"method","any":["cosine rule","cos"]},"field":"all","code":"M2"},{"kind":"M","marks":1,"description":"substitutes 85, 60 and 115 correctly","check":{"type":"contains","value":[85,60,115]},"field":"all","code":"M3"},{"kind":"A","marks":1,"description":"PR = 123.0 km","check":{"type":"numeric","value":123.02725823879493,"dp":1,"tolerance":0.06},"field":"answer","code":"A1","depends":["M3"]}]}},{"id":"p2e-q9::b","maxMarks":3,"sourcePartId":"p2e-q9::b","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"26.2","solution":"By the sine rule, sin(angle QPR)/QR = sin(angle PQR)/PR, that is sin(angle QPR)/60 = sin 115°/123.0273. So sin(angle QPR) = 60 x sin 115° / 123.0273 = 0.442003, giving angle QPR = 26.23 = 26.2°. Angle PQR is obtuse, so angle QPR must be acute and this is the required value.","criteria":[{"kind":"M","marks":1,"description":"uses the sine rule","check":{"type":"method","any":["sine rule","sin"]},"field":"all","code":"M1"},{"kind":"M","marks":1,"description":"substitutes 60, 115 and PR correctly","check":{"type":"contains","value":[60,115,123.0273]},"field":"all","code":"M2"},{"kind":"A","marks":1,"description":"angle QPR = 26.2 degrees","check":{"type":"numeric","value":26.231776370020192,"dp":1,"tolerance":0.06},"field":"answer","ecf":{"uses":["a"],"formula":"asin(60*sin(115)/a)"},"code":"A1","depends":["M2"]}]}},{"id":"p2e-q9::c","maxMarks":3,"sourcePartId":"p2e-q9::c","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"104","solution":"The bearing of Q from P is 078°, and R lies clockwise of Q when viewed from P, so the bearing of R from P is the bearing of Q from P plus angle QPR. That is 78 + 26.2 = 104.2°, which is 104° as a three-figure bearing correct to the nearest degree.","criteria":[{"kind":"M","marks":1,"description":"bearing of R from P = bearing of Q from P + angle QPR","check":{"type":"method","any":["bearing of q from p"]},"field":"all","code":"M1"},{"kind":"M","marks":1,"description":"adds angle QPR to 078 degrees","check":{"type":"contains","value":[78,26.2]},"field":"all","code":"M2"},{"kind":"A","marks":1,"description":"104 degrees","check":{"type":"numeric","value":104.23177637002019,"dp":0,"tolerance":0.51},"field":"answer","ecf":{"uses":["b"],"formula":"78 + b"},"code":"A1","depends":["M2"]}]}},{"id":"p2e-q9::d","maxMarks":2,"sourcePartId":"p2e-q9::d","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"2311.1","solution":"Area = (1/2)(PQ)(QR) sin PQR = (1/2) x 85 x 60 x sin 115° = 2550 x sin 115° = 2311.0849 = 2311.1 km^2, correct to 1 decimal place.","criteria":[{"kind":"M","marks":1,"description":"uses (1/2)ab sin C with 85, 60 and 115","check":{"type":"contains","value":[85,60,115]},"field":"all","code":"M1"},{"kind":"A","marks":1,"description":"area = 2311.1 km^2","check":{"type":"numeric","value":2311.0848569434575,"dp":1,"tolerance":0.06},"field":"answer","code":"A1","depends":["M1"]}]}},{"id":"p2e-q10::k","maxMarks":2,"sourcePartId":"p2e-q10::k","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"2","solution":"det M = (3)(2) - (4)(1) = 6 - 4 = 2.","criteria":[{"kind":"M","marks":1,"description":"uses det M = ad - bc","check":{"type":"anyOf","options":[{"type":"contains","value":[6,4]},{"type":"contains","value":[6,-4]},{"type":"contains","value":[2]},{"type":"method","any":["(3)(2) - (4)(1)","3(2) - 4(1)","3 x 2 - 4 x 1","3*2 - 4*1","ad - bc","ad-bc"]}]},"field":"all","code":"M1"},{"kind":"A","marks":1,"description":"the determinant","check":{"type":"numeric","value":2,"tolerance":0.000001},"field":"answer","code":"A1","depends":["M1"]}]}},{"id":"p2e-q10::a2","maxMarks":3,"sourcePartId":"p2e-q10::a2","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"(1/2)[[2, -4], [-1, 3]]","solution":"For M = [[a, b], [c, d]], M^-1 = (1/det M)[[d, -b], [-c, a]]. Interchange the entries on the leading diagonal, change the sign of the other two, and divide by the determinant: M^-1 = (1/2)[[2, -4], [-1, 3]] = [[1, -2], [-1/2, 3/2]].","criteria":[{"kind":"M","marks":1,"description":"interchanges the leading diagonal entries and changes the sign of the other two","check":{"type":"anyOf","options":[{"type":"contains","value":[2,-4,-1,3]},{"type":"contains","value":[1,-2,-0.5,1.5]}]},"field":"all","code":"M1"},{"kind":"M","marks":1,"description":"divides by the determinant","check":{"type":"contains","value":[0.5,-0.5],"needAll":false,"tolerance":0.005},"field":"all","ecf":{"uses":["k"],"formula":"1/k"},"code":"M2"},{"kind":"A","marks":1,"description":"the inverse matrix","check":{"type":"anyOf","options":[{"type":"matrix","value":[[1,-2],[-0.5,1.5]],"tolerance":0.005},{"type":"contains","value":[0.5,2,-4,-1,3]}]},"field":"answer","code":"A1","depends":["M2"]}]}},{"id":"p2e-q10::b","maxMarks":3,"sourcePartId":"p2e-q10::b","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"[[3, 4], [1, 2]] [[x], [y]] = [[1], [-1]]","solution":"The coefficients of x and y form the matrix M = [[3, 4], [1, 2]], the unknowns form the column matrix X = [[x], [y]], and the constants form the column matrix C = [[1], [-1]]. The pair of equations is therefore [[3, 4], [1, 2]] [[x], [y]] = [[1], [-1]].","criteria":[{"kind":"B","marks":1,"description":"the matrix of coefficients","check":{"type":"contains","value":[3,4,1,2]},"field":"answer","depends":[],"code":"B1"},{"kind":"B","marks":1,"description":"the column matrix of unknowns","check":{"type":"method","any":["[[x], [y]]","[[x],[y]]","(x, y)"]},"field":"answer","depends":[],"code":"B2"},{"kind":"B","marks":1,"description":"the column matrix of constants","check":{"type":"contains","value":[1,-1]},"field":"answer","depends":[],"code":"B3"}]}},{"id":"p2e-q10::c","maxMarks":4,"sourcePartId":"p2e-q10::c","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"x = 3, y = -2","solution":"Multiplying both sides of M X = C on the left by M^-1 gives X = M^-1 C = (1/2)[[2, -4], [-1, 3]] [[1], [-1]] = (1/2)[[(2)(1) + (-4)(-1)], [(-1)(1) + (3)(-1)]] = (1/2)[[6], [-4]] = [[3], [-2]]. So x = 3 and y = -2. Check: 3(3) + 4(-2) = 1.","criteria":[{"kind":"M","marks":1,"description":"multiplies both sides by the inverse matrix","check":{"type":"anyOf","options":[{"type":"method","any":["M^-1 C","M^-1","inverse"]},{"type":"contains","value":[3,-2]}]},"field":"all","code":"M1"},{"kind":"M","marks":1,"description":"multiplies the inverse by the column of constants","check":{"type":"contains","value":[6,-4]},"field":"all","code":"M2"},{"kind":"A","marks":1,"description":"the value of x","check":{"type":"contains","value":[3]},"field":"answer","ecf":{"uses":["k"],"formula":"(6)/k"},"depends":["M1"],"code":"A1"},{"kind":"A","marks":1,"description":"the value of y","check":{"type":"contains","value":[-2]},"field":"answer","ecf":{"uses":["k"],"formula":"(-4)/k"},"depends":["M1"],"code":"A2"}]}}]'::jsonb,false,'draft')
