insert into spark_grading_private.rubrics_v2(subject_id,rubric_version,paper_id,criteria,active,verification_status)
values ('mathematics','source-scheme-draft-v2','p2f','[{"id":"p2f-q1::a","maxMarks":3,"sourcePartId":"p2f-q1::a","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"17/11","solution":"2 1/4 = 9/4, so the numerator is 9/4 - 5/6 = 17/12. The denominator is 2/3 + 1/4 = 11/12. Dividing means multiplying by the reciprocal: 17/12 x 12/11 = 17/11.","criteria":[{"kind":"M","marks":1,"description":"writes the numerator as a single fraction","check":{"type":"contains","value":[1.4166666666666667]},"field":"all","code":"M1"},{"kind":"M","marks":1,"description":"writes the denominator as a single fraction","check":{"type":"contains","value":[0.9166666666666666]},"field":"all","code":"M2"},{"kind":"A","marks":1,"description":"the exact value in its lowest terms","check":{"type":"fraction","value":1.5454545454545454,"simplified":true,"requireFraction":true},"field":"answer","code":"A1","depends":["M2"]}]}},{"id":"p2f-q1::b1","maxMarks":2,"sourcePartId":"p2f-q1::b1","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"1700.00","solution":"850 x 2.00 = BDS$1,700.00.","criteria":[{"kind":"M","marks":1,"description":"multiplies by the exchange rate","check":{"type":"method","any":["x 2.00","exchange rate","850"]},"field":"all","code":"M1"},{"kind":"A","marks":1,"description":"the amount in BDS dollars","check":{"type":"numeric","value":1700,"dp":2,"tolerance":0.011},"field":"answer","code":"A1","depends":["M1"]}]}},{"id":"p2f-q1::b2","maxMarks":2,"sourcePartId":"p2f-q1::b2","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"1675.00","solution":"BDS$1,700.00 - BDS$25 = BDS$1,675.00.","criteria":[{"kind":"M","marks":1,"description":"subtracts the fee from the amount converted","check":{"type":"contains","value":[25]},"field":"all","code":"M1"},{"kind":"A","marks":1,"description":"the amount received","check":{"type":"numeric","value":1675,"dp":2,"tolerance":0.011},"field":"answer","ecf":{"uses":["b1"],"formula":"b1 - 25.0"},"code":"A1","depends":["M1"]}]}},{"id":"p2f-q1::c","maxMarks":2,"sourcePartId":"p2f-q1::c","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"8850.00","solution":"I = PRT/100 = (7,500 x 6 x 3)/100 = BDS$1,350.00. The total amount is 7,500 + 1,350.00 = BDS$8,850.00.","criteria":[{"kind":"M","marks":1,"description":"uses I = PRT/100","check":{"type":"contains","value":[1350]},"field":"all","code":"M1"},{"kind":"A","marks":1,"description":"the total amount","check":{"type":"numeric","value":8850,"dp":2,"tolerance":0.011},"field":"answer","code":"A1","depends":["M1"]}]}},{"id":"p2f-q2::a","maxMarks":2,"sourcePartId":"p2f-q2::a","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"(x + 4)/(x + 3)","solution":"Factorising the numerator: x^2 - 16 = (x - 4)(x + 4). Factorising the denominator: x^2 - x - 12 = (x - 4)(x + 3). The common factor (x - 4) cancels, leaving (x + 4)/(x + 3).","criteria":[{"kind":"M","marks":1,"description":"factorises the numerator","check":{"type":"method","any":["(x - 4)(x + 4)"]},"field":"all","code":"M1"},{"kind":"A","marks":1,"description":"cancels the common factor and gives the fraction in its lowest terms","check":{"type":"expression","value":"(x + 4)/(x + 3)","accepted":["(x+4)/(x+3)"]},"field":"answer","code":"A1","depends":["M2"]}]}},{"id":"p2f-q2::a2","maxMarks":1,"sourcePartId":"p2f-q2::a2","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"The original denominator is zero when x = 4, so the original expression is not defined there","solution":"The original denominator factorises as (x - 4)(x + 3), which is zero when x = 4. An expression whose denominator is zero is not defined, so x = 4 was never allowed, and cancelling the factor does not put it back.","criteria":[{"kind":"B","code":"B1","marks":1,"field":"answer","depends":[],"profile":"reasoning","description":"gives the zero denominator of the original expression as the reason","check":{"type":"prose","key":"the original denominator is zero when x is 4, so it is not defined","tokens":["denominator","zero","0","defined","original"],"mustHave":[],"forbid":[],"polarity":"positive","quorum":0.34}}]}},{"id":"p2f-q2::b","maxMarks":4,"sourcePartId":"p2f-q2::b","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"x = 7/2, y = 3","solution":"Multiplying the second equation by 3: 12x - 3y = 33. Adding 2x + 3y = 16 and 12x - 3y = 33 eliminates y: 14x = 49, so x = 7/2. Substituting x = 7/2 into 2x + 3y = 16 gives 7 + 3y = 16, so 3y = 9 and y = 3.","criteria":[{"kind":"M","marks":1,"description":"eliminates one of the variables","check":{"type":"method","any":["eliminates y","eliminates x"]},"field":"all","code":"M1"},{"kind":"A","marks":1,"description":"the value of x","check":{"type":"equation","value":"x = 7/2"},"field":"all","code":"A1","depends":["M1"]},{"kind":"M","marks":1,"description":"substitutes back to find the second variable","check":{"type":"contains","value":[7]},"field":"all","code":"M2"},{"kind":"A","marks":1,"description":"the value of y","check":{"type":"equation","value":"y = 3"},"field":"all","code":"A2","depends":["M2"]}]}},{"id":"p2f-q2::c","maxMarks":2,"sourcePartId":"p2f-q2::c","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"q = (4p + 5)/3","solution":"Multiplying both sides by 4: 4p = 3q - 5. Adding 5 to both sides: 4p + 5 = 3q. Dividing both sides by 3: q = (4p + 5)/3.","criteria":[{"kind":"M","marks":1,"description":"carries out a correct first step in the rearrangement","check":{"type":"method","any":["4p = 3q - 5"]},"field":"all","code":"M1"},{"kind":"A","marks":1,"description":"q as the subject","check":{"type":"equation","value":"q = (4p + 5)/3"},"field":"answer","code":"A1","depends":["M1"]}]}},{"id":"p2f-q3::a","maxMarks":3,"sourcePartId":"p2f-q3::a","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"10","solution":"Every one of the 50 students is counted exactly once in the Venn diagram, so (30 - x) + x + (25 - x) + 5 = 50. This simplifies to 60 - x = 50, so x = 60 - 50 = 10. So 10 students study both Mathematics and Physics.","criteria":[{"kind":"M","marks":1,"description":"forms an equation in x from the four regions of the Venn diagram","check":{"type":"method","any":["30 - x","30 + 25 - x","60 - x"]},"field":"all","code":"M1"},{"kind":"M","marks":1,"description":"simplifies the equation","check":{"type":"contains","value":[60]},"field":"all","code":"M2"},{"kind":"A","marks":1,"description":"the number who study both Mathematics and Physics","check":{"type":"numeric","value":10,"tolerance":0.000001},"field":"answer","depends":[],"code":"A1"}]}},{"id":"p2f-q3::b","maxMarks":2,"sourcePartId":"p2f-q3::b","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"35","solution":"The number who study Mathematics only is 30 - 10 = 20, and the number who study Physics only is 25 - 10 = 15. So the number who study exactly one of the two subjects is 20 + 15 = 35.","criteria":[{"kind":"M","marks":1,"description":"subtracts the number who study both from each of 30 and 25","check":{"type":"anyOf","options":[{"type":"method","any":["30 - ","25 - "]},{"type":"contains","value":[20,15]},{"type":"contains","value":[35]}]},"field":"all","code":"M1"},{"kind":"A","marks":1,"description":"the number who study exactly one of the two subjects","check":{"type":"numeric","value":35,"tolerance":0.000001},"field":"answer","ecf":{"uses":["a"],"formula":"55 - 2 * a"},"code":"A1","depends":["M1"]}]}},{"id":"p2f-q3::c","maxMarks":2,"sourcePartId":"p2f-q3::c","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"1/10","solution":"5 of the 50 students study neither Mathematics nor Physics, and each student is equally likely to be chosen. So P(neither) = 5/50 = 1/10.","criteria":[{"kind":"M","marks":1,"description":"uses P(neither) = (the number who study neither)/(the total number of students)","check":{"type":"anyOf","options":[{"type":"contains","value":[5,50]},{"type":"contains","value":[0.1]}]},"field":"all","code":"M1"},{"kind":"A","marks":1,"description":"the probability in its lowest terms","check":{"type":"fraction","value":0.1,"simplified":true,"requireFraction":true},"field":"answer","code":"A1","depends":["M1"]}]}},{"id":"p2f-q3::d","maxMarks":2,"sourcePartId":"p2f-q3::d","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"The shaded region represents the students who study Mathematics only, that is, the students who study Mathematics but not Physics.","solution":"The shading covers the part of the Mathematics circle that lies outside the Physics circle, so it is the set of students who study Mathematics but do not study Physics - the students who study Mathematics only. Naming Mathematics earns 1 mark and making it clear that these students do not study Physics earns the second.","criteria":[{"kind":"B","marks":1,"description":"says that the students study Mathematics","check":{"type":"written","id":"subject","description":"says that the students study Mathematics","any":["mathematics"]},"field":"answer","code":"B1"},{"kind":"B","marks":1,"description":"makes it clear that they do not study Physics","check":{"type":"written","id":"excludes","description":"makes it clear that they do not study Physics","any":["mathematics only","but not physics","do not study physics","not study physics"]},"field":"answer","code":"B2"}]}},{"id":"p2f-q4::a1","maxMarks":3,"sourcePartId":"p2f-q4::a1","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"the perpendicular bisector of AB through M, with the construction arcs shown","solution":"Open the compasses to more than half of AB, that is to more than 4 cm. With centre A draw arcs above and below AB; with the SAME radius and centre B draw two more to cut them. Rule the line through the two crossing points. It cuts AB at the midpoint M and makes an angle of 90° with AB. The arcs must be left on the page.","criteria":null}},{"id":"p2f-q4::a2","maxMarks":1,"sourcePartId":"p2f-q4::a2","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"the bisector of angle TMB drawn from M, with the arc at M and the two equal arcs from where it cuts MT and MB shown","solution":"With centre M draw an arc cutting MT and MB. From each of those two crossing points, with the same radius, draw an arc so that the two arcs cross. Rule the line from M through that crossing point. This mark is for the arcs: an angle measured with a protractor earns nothing here.","criteria":null}},{"id":"p2f-q4::b","maxMarks":1,"sourcePartId":"p2f-q4::b","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"45","solution":"MT is perpendicular to AB, so angle TMB = 90°. The bisector halves it, so angle TMR = 90/2 = 45°.","criteria":[{"kind":"B","marks":1,"description":"the size of the constructed angle","check":{"type":"numeric","value":45,"tolerance":0.011},"field":"answer","depends":[],"code":"B1"}]}},{"id":"p2f-q4::c1","maxMarks":2,"sourcePartId":"p2f-q4::c1","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"192500","solution":"Volume of a cylinder = π x r^2 x h = 22/7 x 35^2 x 50 = 22/7 x 1225 x 50 = 192500 cm^3.","criteria":[{"kind":"M","marks":1,"description":"uses V = pi x r^2 x h with r = 35 and h = 50","check":{"type":"contains","value":[1225]},"field":"all","code":"M1"},{"kind":"A","marks":1,"description":"the volume of the drum","check":{"type":"numeric","value":192500,"tolerance":0.011},"field":"answer","code":"A1","depends":["M1"]}]}},{"id":"p2f-q4::c2","maxMarks":2,"sourcePartId":"p2f-q4::c2","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"192.5","solution":"192500 cm^3 = 192500/1000 litres = 192.5 litres.","criteria":[{"kind":"M","marks":1,"description":"divides the volume in cm^3 by 1000","check":{"type":"method","any":["1000"]},"field":"all","code":"M1"},{"kind":"A","marks":1,"description":"the capacity in litres","check":{"type":"numeric","value":192.5,"tolerance":0.011},"field":"answer","ecf":{"uses":["c1"],"formula":"c1 / 1000"},"code":"A1","depends":["M1"]}]}},{"id":"p2f-q5::a","maxMarks":2,"sourcePartId":"p2f-q5::a","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"15, 33, 42, 50","solution":"Add each frequency to the running total: 4 + 11 = 15, 15 + 18 = 33, 33 + 9 = 42, 42 + 8 = 50.","criteria":null}},{"id":"p2f-q5::b","maxMarks":3,"sourcePartId":"p2f-q5::b","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"the points (10, 4), (20, 15), (30, 33), (40, 42), (50, 50) joined by a smooth curve","solution":"Plot the cumulative frequency at the upper boundary of each class: (10, 4), (20, 15), (30, 33), (40, 42), (50, 50), then join them with a smooth curve.","criteria":null}},{"id":"p2f-q5::c","maxMarks":2,"sourcePartId":"p2f-q5::c","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"25.6","solution":"The median is the 25th value. Reading across from 25 on the cumulative frequency axis to the curve and down to the horizontal axis gives about 25.6 kg. By interpolation the exact value is 20 + (25 - 15)/18 x 10 = 25.6 kg. Any reading from 23 kg to 28 kg is acceptable.","criteria":[{"kind":"M","marks":1,"description":"reads across from 25 on the cumulative frequency axis","check":{"type":"contains","value":[25]},"field":"all","code":"M1"},{"kind":"A","marks":1,"description":"the median","check":{"type":"numeric","value":25.555555555555557,"tolerance":2.5},"field":"answer","code":"A1","depends":["M1"]}]}},{"id":"p2f-q5::d","maxMarks":2,"sourcePartId":"p2f-q5::d","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"17/50","solution":"33 of the 50 values are 30 kg or less, so 50 - 33 = 17 are more than 30 kg. The probability is 17/50.","criteria":[{"kind":"M","marks":1,"description":"finds the number greater than 30 kg","check":{"type":"contains","value":[17]},"field":"all","code":"M1"},{"kind":"A","marks":1,"description":"the probability in its lowest terms","check":{"type":"fraction","value":0.34,"simplified":true,"requireFraction":true},"field":"answer","code":"A1","depends":["M1"]}]}},{"id":"p2f-q6::a","maxMarks":3,"sourcePartId":"p2f-q6::a","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"135","solution":"The 8 exterior angles of the polygon add up to 360°, so each exterior angle is 360°/8 = 45°. An interior angle and its exterior angle lie on a straight line, so x = 180 - 45 = 135°.","criteria":[{"kind":"M","marks":1,"description":"uses exterior angle = 360/8","check":{"type":"contains","value":[45]},"field":"all","code":"M1"},{"kind":"M","marks":1,"description":"uses interior angle = 180 - exterior angle","check":{"type":"contains","value":[180]},"field":"all","code":"M2"},{"kind":"A","marks":1,"description":"the interior angle of the regular octagon","check":{"type":"numeric","value":135,"tolerance":0.011},"field":"answer","code":"A1","depends":["M2"]}]}},{"id":"p2f-q6::b","maxMarks":2,"sourcePartId":"p2f-q6::b","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"58","solution":"y and the angle of 58° are alternate angles between the parallel lines PQ and RS, so they are equal. y = 58.","criteria":[{"kind":"M","marks":1,"description":"identifies the pair as alternate angles","check":{"type":"method","any":["alternate"]},"field":"all","code":"M1"},{"kind":"A","marks":1,"description":"the value of y","check":{"type":"numeric","value":58,"tolerance":0.011},"field":"answer","code":"A1","depends":["M1"]}]}},{"id":"p2f-q6::c","maxMarks":2,"sourcePartId":"p2f-q6::c","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"y and the angle of 58 degrees are alternate angles between the parallel lines PQ and RS, so the two angles are equal.","solution":"PQ is parallel to RS. The angle marked y and the angle of 58° are alternate angles, and alternate angles between parallel lines are equal. Naming them as alternate angles earns 1 mark and saying that the lines PQ and RS are parallel earns the second.","criteria":[{"kind":"B","marks":1,"description":"names the angles as alternate angles","check":{"type":"written","id":"name","description":"names the angles as alternate angles","any":["alternate"],"none":["corresponding","co-interior"]},"field":"answer","code":"B1"},{"kind":"B","marks":1,"description":"says that PQ and RS are parallel","check":{"type":"written","id":"parallel","description":"says that PQ and RS are parallel","any":["parallel"]},"field":"answer","code":"B2"}]}},{"id":"p2f-q6::d","maxMarks":2,"sourcePartId":"p2f-q6::d","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"15","solution":"Each exterior angle is 180 - 156 = 24°. The exterior angles add up to 360°, so the number of sides is 360/24 = 15.","criteria":[{"kind":"M","marks":1,"description":"finds the exterior angle as 180 - the interior angle","check":{"type":"contains","value":[24]},"field":"all","code":"M1"},{"kind":"A","marks":1,"description":"the number of sides","check":{"type":"numeric","value":15,"tolerance":0.011},"field":"answer","code":"A1","depends":["M1"]}]}},{"id":"p2f-q7::a","maxMarks":4,"sourcePartId":"p2f-q7::a","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"16, 20, 100, 44","solution":"Each figure has one more shaded tile along each side than the figure before, so the shaded tiles are the square numbers and Figure 4 has 4 x 4 = 16 of them. The border grows by 4 tiles each time, from 8 to 12 to 16, so Figure 4 has 20 unshaded tiles. Figure 10 is too large to draw, so use the rules: it has 10 x 10 = 100 shaded tiles and 4 x 10 + 4 = 44 unshaded tiles.","criteria":null}},{"id":"p2f-q7::b","maxMarks":2,"sourcePartId":"p2f-q7::b","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"4n + 4","solution":"The border is one tile deep all the way round the n by n block, so it holds n tiles along each of the four sides and one tile at each of the four corners: 4n + 4 tiles. Checking against the table, n = 3 gives 16 and n = 4 gives 20.","criteria":[{"kind":"M","marks":1,"description":"shows how the unshaded tiles is built up in Figure n","check":{"type":"contains","value":[4]},"field":"all","code":"M1"},{"kind":"A","marks":1,"description":"the expression for the unshaded tiles","check":{"type":"expression","value":"4n + 4","accepted":["4(n + 1)","4n + 4"]},"field":"answer","code":"A1","depends":["M1"]}]}},{"id":"p2f-q7::c","maxMarks":2,"sourcePartId":"p2f-q7::c","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"17","solution":"The total number of tiles in Figure n is n^2 + 4n + 4, which is (n + 2)^2. So (n + 2)^2 = 361, giving n + 2 = 19 by taking the positive square root, and n = 17. The figure is Figure 17. Check: 17^2 + 4 x 17 + 4 = 289 + 68 + 4 = 361.","criteria":[{"kind":"M","marks":1,"description":"writes the equation (n + 2)^2 = 361 for the total number of tiles","check":{"type":"contains","value":[361]},"field":"all","code":"M1"},{"kind":"A","marks":1,"description":"the figure number","check":{"type":"numeric","value":17,"tolerance":0.000001},"field":"answer","code":"A1","depends":["M1"]}]}},{"id":"p2f-q7::d","maxMarks":2,"sourcePartId":"p2f-q7::d","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"The number of unshaded tiles in Figure n is 4n + 4, which is 4(n + 1), so it is always a multiple of 4. 30 is not a multiple of 4, because 30 divided by 4 is 7.5, which is not a whole number. There is therefore no figure with exactly 30 unshaded tiles.","solution":"The border holds 4n + 4 = 4(n + 1) tiles, so the number of unshaded tiles is always a multiple of 4: 8, 12, 16, 20, and so on. Saying that the number of unshaded tiles is 4(n + 1), a multiple of 4, earns 1 mark. Saying that 30 is not a multiple of 4, or that 4n + 4 = 30 gives n = 6.5, which is not a whole number, earns the second.","criteria":[{"kind":"B","marks":1,"description":"states that the number of unshaded tiles is 4n + 4 = 4(n + 1), always a multiple of 4","check":{"type":"written","id":"form","description":"states that the number of unshaded tiles is 4n + 4 = 4(n + 1), always a multiple of 4","any":["multiple of 4","4(n + 1)","divisible by 4"]},"field":"answer","code":"B1"},{"kind":"B","marks":1,"description":"states that 30 is not a multiple of 4, so n would not be a whole number","check":{"type":"written","id":"why","description":"states that 30 is not a multiple of 4, so n would not be a whole number","any":["30 is not a multiple of 4","not a whole number","not an integer","7.5"]},"field":"answer","code":"B2"}]}},{"id":"p2f-q8::a","maxMarks":4,"sourcePartId":"p2f-q8::a","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"x + y <= 30; 2x + y <= 40","solution":"At most 30 in total gives x + y ≤ 30. The second condition gives 2x + y ≤ 40.","criteria":[{"kind":"B","marks":2,"description":"the first inequality","check":{"type":"allOf","options":[{"type":"inequality","value":"x + y <= 30"}]},"field":"answer","depends":[],"code":"B1"},{"kind":"B","marks":2,"description":"the second inequality","check":{"type":"allOf","options":[{"type":"inequality","value":"2x + y <= 40"}]},"field":"answer","depends":[],"code":"B2"}]}},{"id":"p2f-q8::b","maxMarks":2,"sourcePartId":"p2f-q8::b","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"P = 8x + 5y","solution":"Each of the x shirts earns $8 and each of the y dresses earns $5, so P = 8x + 5y.","criteria":[{"kind":"M","marks":1,"description":"uses $8 for each of the x shirts","check":{"type":"contains","value":[8]},"field":"all","code":"M1"},{"kind":"A","marks":1,"description":"the expression for the profit","check":{"type":"anyOf","options":[{"type":"equation","value":"P = 8x + 5y"},{"type":"expression","value":"8x + 5y"}]},"field":"answer","code":"A1","depends":["M1"]}]}},{"id":"p2f-q8::c","maxMarks":4,"sourcePartId":"p2f-q8::c","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"$150, $180, $160","solution":"Substitute each vertex into P = 8x + 5y: at (0, 30), P = 8(0) + 5(30) = $150; at (10, 20), P = 8(10) + 5(20) = $180; at (20, 0), P = 8(20) + 5(0) = $160.","criteria":[{"kind":"M","marks":1,"description":"substitutes the vertices into P = 8x + 5y","check":{"type":"contains","value":[150]},"field":"all","code":"M1"},{"kind":"M","marks":1,"description":"evaluates the profit at every vertex","check":{"type":"contains","value":[180]},"field":"all","code":"M2"},{"kind":"A","marks":2,"description":"all three profits","check":{"type":"set","value":[150,180,160],"tolerance":0.000001},"field":"answer","code":"A1","depends":["M2"]}]}},{"id":"p2f-q8::d","maxMarks":2,"sourcePartId":"p2f-q8::d","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"10 shirts and 20 dresses, giving a profit of $180","solution":"The greatest of the profits is $180, at the vertex (10, 20). So 10 shirts and 20 dresses should be made.","criteria":[{"kind":"M","marks":1,"description":"selects the vertex giving the greatest profit","check":{"type":"contains","value":[180]},"field":"all","code":"M1"},{"kind":"A","marks":1,"description":"10 shirts and 20 dresses","check":{"type":"set","value":[10,20,180],"tolerance":0.000001},"field":"answer","code":"A1","depends":["M1"]}]}},{"id":"p2f-q9::a","maxMarks":3,"sourcePartId":"p2f-q9::a","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"23.4","solution":"Triangle TBA is right-angled at B, so tan 38° = TB/AB = TB/30. Therefore TB = 30 x tan 38° = 23.4386 = 23.4 m, correct to 1 decimal place.","criteria":[{"kind":"M","marks":1,"description":"uses tan = opposite/adjacent in triangle TBA","check":{"type":"method","any":["tan"]},"field":"all","code":"M1"},{"kind":"M","marks":1,"description":"substitutes to give TB = 30 tan 38","check":{"type":"contains","value":[30,38]},"field":"all","code":"M2"},{"kind":"A","marks":1,"description":"TB = 23.4 m","check":{"type":"numeric","value":23.438568795201522,"dp":1,"tolerance":0.06},"field":"answer","code":"A1","depends":["M2"]}]}},{"id":"p2f-q9::b","maxMarks":4,"sourcePartId":"p2f-q9::b","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"28.0","solution":"Triangle TBC is right-angled at B, so tan 22° = TB/CB, which gives CB = TB / tan 22°. So CB = 23.4386 / tan 22° = 58.01 m. Since A lies between C and B, AC = CB - AB = 58.01 - 30 = 28.01 = 28.0 m, correct to 1 decimal place.","criteria":[{"kind":"M","marks":1,"description":"uses tan 22 = TB/CB in triangle TBC","check":{"type":"method","any":["tan"]},"field":"all","code":"M1"},{"kind":"M","marks":1,"description":"rearranges to CB = TB / tan 22","check":{"type":"contains","value":[22,23.4386]},"field":"all","code":"M2"},{"kind":"M","marks":1,"description":"CB = 58.01 m and AC = CB - 30","check":{"type":"contains","value":[58.01,30]},"field":"all","code":"M3"},{"kind":"A","marks":1,"description":"AC = 28.0 m","check":{"type":"numeric","value":28.01249348789672,"dp":1,"tolerance":0.06},"field":"answer","ecf":{"uses":["a"],"formula":"a/tan(22) - 30"},"code":"A1","depends":["M3"]}]}},{"id":"p2f-q9::c","maxMarks":3,"sourcePartId":"p2f-q9::c","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"43.2","solution":"The angle of depression of D from T is equal to the angle of elevation of T from D, which is angle TDB. Triangle TBD is right-angled at B, with TB = 23.4386 m and BD = 25 m, so tan(angle TDB) = TB/BD = 0.9375. So angle TDB = 43.15 = 43.2°, and the angle of depression of D from T is 43.2°, correct to 1 decimal place.","criteria":[{"kind":"M","marks":1,"description":"uses tan(angle TDB) = TB/BD in triangle TBD","check":{"type":"method","any":["tan"]},"field":"all","code":"M1"},{"kind":"M","marks":1,"description":"substitutes TB and BD = 25 correctly","check":{"type":"contains","value":[23.4386,25]},"field":"all","code":"M2"},{"kind":"A","marks":1,"description":"angle of depression = 43.2 degrees","check":{"type":"numeric","value":43.153693389213196,"dp":1,"tolerance":0.06},"field":"answer","ecf":{"uses":["a"],"formula":"atan(a/25)"},"code":"A1","depends":["M2"]}]}},{"id":"p2f-q9::d","maxMarks":2,"sourcePartId":"p2f-q9::d","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"The horizontal line drawn through T is parallel to the level ground AB, and AT is a transversal cutting both of them. The angle of elevation of T from A and the angle of depression of A from T are therefore alternate angles between parallel lines, and alternate angles are equal.","solution":"The angle of elevation is measured at A from the horizontal ground AB up to AT, and the angle of depression is measured at T from the horizontal line through T down to TA. The horizontal line through T is parallel to AB because both are horizontal, and AT is a transversal cutting this pair of parallel lines. The two angles are alternate angles (Z angles) between the parallel lines, so they are equal.","criteria":[{"kind":"B","marks":1,"description":"states that the horizontal line through T is parallel to the ground AB","check":{"type":"written","id":"r1","description":"states that the horizontal line through T is parallel to the ground AB","any":["parallel"]},"field":"answer","code":"B1"},{"kind":"B","marks":1,"description":"identifies the two angles as alternate angles, which are equal","check":{"type":"written","id":"r2","description":"identifies the two angles as alternate angles, which are equal","any":["alternate","z angles"]},"field":"answer","code":"B2"}]}},{"id":"p2f-q10::a1","maxMarks":2,"sourcePartId":"p2f-q10::a1","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"b - a","solution":"\\vec{AB} = \\vec{AO} + \\vec{OB} = -a + b = b - a.","criteria":[{"kind":"M","marks":1,"description":"uses \\vec{AB} = \\vec{AO} + \\vec{OB}","check":{"type":"method","any":["\\vec{AO} + \\vec{OB}","AO + OB","-a + b","b - a"]},"field":"all","code":"M1"},{"kind":"A","marks":1,"description":"the expression for \\vec{AB}","check":{"type":"expression","value":"b - a","accepted":["-a + b"]},"field":"answer","code":"A1","depends":["M1"]}]}},{"id":"p2f-q10::a2","maxMarks":2,"sourcePartId":"p2f-q10::a2","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"(1/2)b - a","solution":"N is the midpoint of OB, so \\vec{ON} = (1/2)b. Then \\vec{AN} = \\vec{AO} + \\vec{ON} = -a + (1/2)b = (1/2)b - a.","criteria":[{"kind":"M","marks":1,"description":"uses \\vec{ON} = (1/2)b","check":{"type":"method","any":["\\vec{ON} = (1/2)b","(1/2)b","b/2","0.5b","1/2 b","(b - 2a)"]},"field":"all","code":"M1"},{"kind":"A","marks":1,"description":"the expression for \\vec{AN}","check":{"type":"expression","value":"(1/2)b - a","accepted":["-a + (1/2)b","(b - 2a)/2"]},"field":"answer","code":"A1","depends":["M1"]}]}},{"id":"p2f-q10::b","maxMarks":3,"sourcePartId":"p2f-q10::b","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"(1/2)b - (1/2)a","solution":"M is the midpoint of OA, so \\vec{OM} = (1/2)a, and \\vec{ON} = (1/2)b. Then \\vec{MN} = \\vec{MO} + \\vec{ON} = -(1/2)a + (1/2)b = (1/2)(b - a).","criteria":[{"kind":"M","marks":1,"description":"writes \\vec{OM} = (1/2)a and \\vec{ON} = (1/2)b","check":{"type":"method","any":["\\vec{OM} = (1/2)a","(1/2)a","a/2","0.5a","(1/2)(b - a)","(b - a)/2"]},"field":"all","code":"M1"},{"kind":"M","marks":1,"description":"uses \\vec{MN} = \\vec{MO} + \\vec{ON}","check":{"type":"method","any":["\\vec{MO} + \\vec{ON}","\\vec{ON} - \\vec{OM}","MO + ON","(1/2)b - (1/2)a","(1/2)(b - a)","(b - a)/2","0.5b - 0.5a"]},"field":"all","code":"M2"},{"kind":"A","marks":1,"description":"the simplified expression for \\vec{MN}","check":{"type":"expression","value":"(1/2)b - (1/2)a","accepted":["(1/2)(b - a)","(b - a)/2"]},"field":"answer","code":"A1","depends":["M2"]}]}},{"id":"p2f-q10::c","maxMarks":3,"sourcePartId":"p2f-q10::c","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"\\vec{MN} = (1/2)(b - a) = (1/2)\\vec{AB}, so \\vec{MN} is a scalar multiple of \\vec{AB} and MN is parallel to AB. In the quadrilateral ABNM the sides AB and NM are parallel, but BN and MA are not, so exactly one pair of opposite sides is parallel and ABNM is a trapezium.","solution":"From (a) (i), \\vec{AB} = b - a, and from (b), \\vec{MN} = (1/2)(b - a). Hence \\vec{MN} = (1/2)\\vec{AB}. One vector is a scalar multiple of the other, so MN is parallel to AB and half its length. In ABNM the sides AB and NM are therefore parallel, while \\vec{BN} = -(1/2)b and \\vec{MA} = (1/2)a are not parallel, because a and b are not parallel. A quadrilateral with exactly one pair of parallel sides is a trapezium.","criteria":[{"kind":"B","marks":1,"description":"shows that \\vec{MN} is (1/2)\\vec{AB}, a scalar multiple of it","check":{"type":"written","id":"multiple","description":"shows that \\vec{MN} is (1/2)\\vec{AB}, a scalar multiple of it","any":["scalar multiple","multiple of","1/2","half","0.5"]},"field":"answer","code":"B1"},{"kind":"B","marks":1,"description":"states that MN is parallel to AB","check":{"type":"written","id":"parallel","description":"states that MN is parallel to AB","any":["parallel","same direction","same gradient"]},"field":"answer","code":"B2"},{"kind":"B","marks":1,"description":"names ABNM as a trapezium","check":{"type":"written","id":"trapezium","description":"names ABNM as a trapezium","any":["trapezium","trapezoid"]},"field":"answer","code":"B3"}]}},{"id":"p2f-q10::d","maxMarks":2,"sourcePartId":"p2f-q10::d","kind":"structured","acceptedPhrases":[],"sourceFormat":"math-paper2","sourceMarking":{"answer":"sqrt(34)","solution":"\\vec{AB} = b - a = [[8], [4]] - [[3], [1]] = [[5], [3]]. So |\\vec{AB}| = sqrt((5)^2 + (3)^2) = sqrt(25 + 9) = sqrt(34), which is 5.83 correct to 2 decimal places.","criteria":[{"kind":"M","marks":1,"description":"uses |v| = sqrt(x^2 + y^2)","check":{"type":"anyOf","options":[{"type":"contains","value":[34]},{"type":"contains","value":[25,9]}]},"field":"all","code":"M1"},{"kind":"A","marks":1,"description":"the magnitude of \\vec{AB}","check":{"type":"anyOf","options":[{"type":"expression","value":"sqrt(34)","accepted":["5.83"]},{"type":"numeric","value":5.830951894845301,"tolerance":0.01}]},"field":"answer","depends":[],"code":"A1"}]}}]'::jsonb,false,'draft')
