},{"id":"ss-p2-c-q3::(c) (i)","maxMarks":4,"sourcePartId":"ss-p2-c-q3::(c) (i)","kind":"structured","acceptedPhrases":[],"sourceFormat":"social-studies-paper2","sourceMarking":{"marking":{"type":"developed_points","maxPoints":2,"maxMarks":4,"profile":"UK","points":[{"id":"jobs","label":"Create suitable skilled employment","concepts":["job_creation"],"developmentConcepts":["retain_workers"],"allowGeneralDevelopment":true},{"id":"pay","label":"Improve salaries and compensation","concepts":["better_wages"],"developmentConcepts":["retain_workers"],"allowGeneralDevelopment":true},{"id":"conditions","label":"Improve working conditions","concepts":["better_work_conditions"],"developmentConcepts":["retain_workers"],"allowGeneralDevelopment":true},{"id":"career","label":"Expand professional development","concepts":["career_development"],"developmentConcepts":["retain_workers"],"allowGeneralDevelopment":true},{"id":"services","label":"Improve public services and quality of life","concepts":["improve_social_services"],"developmentConcepts":["retain_workers"],"allowGeneralDevelopment":true}]},"guide":["Actions may address jobs, pay, working conditions, career development or quality of life."],"sourceIndex":2}},{"id":"ss-p2-c-q3::(c) (ii)","maxMarks":4,"sourcePartId":"ss-p2-c-q3::(c) (ii)","kind":"structured","acceptedPhrases":[],"sourceFormat":"social-studies-paper2","sourceMarking":{"marking":{"type":"linked_development","maxPoints":2,"maxMarks":4,"followFromPartIndex":2,"profile":"UK","links":[{"id":"jobs","label":"Explains why suitable employment encourages retention","triggerConcepts":["job_creation"],"resultConcepts":["retain_workers","employment"]},{"id":"pay","label":"Explains why better pay encourages retention","triggerConcepts":["better_wages"],"resultConcepts":["retain_workers"]},{"id":"conditions","label":"Explains why better working conditions encourage retention","triggerConcepts":["better_work_conditions"],"resultConcepts":["retain_workers"]},{"id":"career","label":"Explains why career opportunities encourage retention","triggerConcepts":["career_development"],"resultConcepts":["retain_workers"]},{"id":"services","label":"Explains why quality-of-life improvements encourage retention","triggerConcepts":["improve_social_services"],"resultConcepts":["retain_workers"]}]},"guide":["Link each action to a reason skilled workers would be more willing to remain."],"sourceIndex":3}},{"id":"ss-p2-c-q4::(a)","maxMarks":2,"sourcePartId":"ss-p2-c-q4::(a)","kind":"structured","acceptedPhrases":[],"sourceFormat":"social-studies-paper2","sourceMarking":{"marking":{"type":"list","maxPoints":2,"maxMarks":2,"marksPerPoint":1,"profile":"KC","points":[{"id":"caricom","label":"CARICOM","concepts":["caricom"]},{"id":"csme","label":"CSME","concepts":["csme"]},{"id":"oecs","label":"OECS","concepts":["oecs"]},{"id":"ccj","label":"CCJ","concepts":["ccj"]}]},"guide":["Any two relevant institutions or arrangements."],"sourceIndex":0}},{"id":"ss-p2-c-q4::(b)","maxMarks":4,"sourcePartId":"ss-p2-c-q4::(b)","kind":"structured","acceptedPhrases":[],"sourceFormat":"social-studies-paper2","sourceMarking":{"marking":{"type":"developed_points","maxPoints":2,"maxMarks":4,"profile":"UK","points":[{"id":"services","label":"Supports remote and exportable services","concepts":["ict_remote_services"],"developmentConcepts":["employment","foreign_exchange"],"allowGeneralDevelopment":true},{"id":"commerce","label":"Expands e-commerce and market access","concepts":["ict_ecommerce"],"developmentConcepts":["larger_market","more_regional_trade"],"allowGeneralDevelopment":true},{"id":"education","label":"Expands education and training access","concepts":["ict_education"],"developmentConcepts":["human_resource_development"],"allowGeneralDevelopment":true},{"id":"efficiency","label":"Improves communication and efficiency","concepts":["ict_efficiency"],"developmentConcepts":["value_added"],"allowGeneralDevelopment":true}]},"guide":["Develop two valid contributions such as e-commerce, remote services, education or efficiency."],"sourceIndex":1}},{"id":"ss-p2-c-q4::(c) (i)","maxMarks":4,"sourcePartId":"ss-p2-c-q4::(c) (i)","kind":"structured","acceptedPhrases":[],"sourceFormat":"social-studies-paper2","sourceMarking":{"marking":{"type":"developed_points","maxPoints":2,"maxMarks":4,"profile":"UK","points":[{"id":"customs","label":"Use electronic and harmonised customs procedures","concepts":["digital_trade","harmonise_customs"],"developmentConcepts":["faster_trade","lower_trade_costs"],"allowGeneralDevelopment":true},{"id":"standards","label":"Adopt common regional standards for digital transactions","concepts":["common_standards"],"developmentConcepts":["more_regional_trade"],"allowGeneralDevelopment":true},{"id":"finance","label":"Improve payment and trade-finance access","concepts":["trade_finance"],"developmentConcepts":["more_regional_trade"],"allowGeneralDevelopment":true},{"id":"platform","label":"Support regional e-commerce platforms","concepts":["ict_ecommerce","digital_trade"],"developmentConcepts":["larger_market","more_regional_trade"],"allowGeneralDevelopment":true}]},"guide":["Actions should reduce cross-border barriers or improve regional digital market access."],"sourceIndex":2}},{"id":"ss-p2-c-q4::(c) (ii)","maxMarks":4,"sourcePartId":"ss-p2-c-q4::(c) (ii)","kind":"structured","acceptedPhrases":[],"sourceFormat":"social-studies-paper2","sourceMarking":{"marking":{"type":"linked_development","maxPoints":2,"maxMarks":4,"followFromPartIndex":2,"profile":"UK","links":[{"id":"customs","label":"Explains why digital or harmonised customs helps trade","triggerConcepts":["digital_trade","harmonise_customs"],"resultConcepts":["faster_trade","lower_trade_costs"]},{"id":"standards","label":"Explains why common standards help trade","triggerConcepts":["common_standards"],"resultConcepts":["more_regional_trade","faster_trade"]},{"id":"finance","label":"Explains why finance or payment access helps trade","triggerConcepts":["trade_finance"],"resultConcepts":["more_regional_trade"]},{"id":"platform","label":"Explains why e-commerce platforms expand trade","triggerConcepts":["ict_ecommerce"],"resultConcepts":["larger_market","more_regional_trade"]}]},"guide":["Show how the action lowers cost, reduces delays or expands market access."],"sourceIndex":3}},{"id":"ss-p2-c-q5::content","maxMarks":18,"sourcePartId":"ss-p2-c-q5::content","kind":"structured","acceptedPhrases":[],"sourceFormat":"social-studies-essay","sourceMarking":{"tasks":["Define democracy.","Outline ONE function of government other than providing social services.","Describe TWO ways political parties prepare for elections.","Suggest THREE strategies government could use to maintain adequate social services.","Explain why any TWO of the suggested strategies are likely to be successful."],"guide":["Use a clear essay structure.","Keep political-party activities separate from government responsibilities.","Develop each proposed strategy with a practical result."],"component":"content"}},{"id":"ss-p2-c-q5::organisation","maxMarks":4,"sourcePartId":"ss-p2-c-q5::organisation","kind":"structured","acceptedPhrases":[],"sourceFormat":"social-studies-essay","sourceMarking":{"tasks":["Define democracy.","Outline ONE function of government other than providing social services.","Describe TWO ways political parties prepare for elections.","Suggest THREE strategies government could use to maintain adequate social services.","Explain why any TWO of the suggested strategies are likely to be successful."],"component":"organisation"}},{"id":"ss-p2-c-q6::content","maxMarks":18,"sourcePartId":"ss-p2-c-q6::content","kind":"structured","acceptedPhrases":[],"sourceFormat":"social-studies-essay","sourceMarking":{"tasks":["Define climate-change adaptation.","Identify TWO effects of climate change on Caribbean communities.","Explain TWO ways households or communities may adapt to climate impacts.","Suggest THREE government measures that could strengthen climate resilience.","Explain why any TWO of the suggested measures are likely to be successful."],"guide":["Use essay format with coherent paragraphs.","Distinguish adaptation from measures that reduce the causes of climate change.","Use Caribbean examples where relevant."],"component":"content"}},{"id":"ss-p2-c-q6::organisation","maxMarks":4,"sourcePartId":"ss-p2-c-q6::organisation","kind":"structured","acceptedPhrases":[],"sourceFormat":"social-studies-essay","sourceMarking":{"tasks":["Define climate-change adaptation.","Identify TWO effects of climate change on Caribbean communities.","Explain TWO ways households or communities may adapt to climate impacts.","Suggest THREE government measures that could strengthen climate resilience.","Explain why any TWO of the suggested measures are likely to be successful."],"component":"organisation"}}]'::jsonb,false,'draft')
