insert into spark_grading_private.rubrics_v2(subject_id,rubric_version,paper_id,criteria,active,verification_status)
values ('food-nutrition-and-health','source-scheme-draft-v2','practice-01','[{"id":"FNH-SPARK-P2-ORIGINAL-01-Q1::a","maxMarks":2,"sourcePartId":"FNH-SPARK-P2-ORIGINAL-01-Q1::a","kind":"structured","acceptedPhrases":[],"sourceFormat":"fnh-paper2","sourceMarking":{"modelPoints":["Diet means the usual foods and drinks consumed by a person.","Diet influences physical and nutritional wellbeing by supplying energy and nutrients."],"explanation":"Diet includes all habitual foods and drinks, not only diets intended for weight loss.","keywords":["diet","foods and drinks"],"profile":"knowledge"}},{"id":"FNH-SPARK-P2-ORIGINAL-01-Q1::b","maxMarks":4,"sourcePartId":"FNH-SPARK-P2-ORIGINAL-01-Q1::b","kind":"structured","acceptedPhrases":[],"sourceFormat":"fnh-paper2","sourceMarking":{"modelPoints":["Household income or available money.","Price and seasonal availability.","Culture, tradition or religion.","Access to shops, transport or food storage.","Health conditions, allergies or dietary requirements.","Advertising, convenience or time to prepare food."],"explanation":"Any four distinct factors with sensible examples earn credit.","keywords":[],"profile":"knowledge"}},{"id":"FNH-SPARK-P2-ORIGINAL-01-Q1::c","maxMarks":4,"sourcePartId":"FNH-SPARK-P2-ORIGINAL-01-Q1::c","kind":"structured","acceptedPhrases":[],"sourceFormat":"fnh-paper2","sourceMarking":{"modelPoints":["Interrupted roads or deliveries reduce availability; organise safe community food distribution.","Lost income raises barriers to purchasing food; arrange targeted school/community food assistance.","Flood damage harms crops and food safety; coordinate safe water, storage and local agriculture support.","Power cuts affect cold storage; ensure safe refrigeration or use shelf-stable food appropriately."],"explanation":"Award 2 marks for each correctly linked threat and response; avoid giving unsafe food recommendations.","keywords":[],"profile":"use-of-knowledge"}},{"id":"FNH-SPARK-P2-ORIGINAL-01-Q1::d","maxMarks":6,"sourcePartId":"FNH-SPARK-P2-ORIGINAL-01-Q1::d","kind":"structured","acceptedPhrases":[],"sourceFormat":"fnh-paper2","sourceMarking":{"modelPoints":["Identify target groups such as children, pregnant adults or older adults and assess their needs.","Provide a realistic food support action using safe, varied locally available items.","Include food-safety and clean-water measures.","Offer nutrition education using culturally familiar examples.","Name suitable partners such as schools, public-health clinics or community groups.","Describe one measurable indicator such as meal uptake, attendance or dietary variety."],"explanation":"One mark per supported component; the plan must fit the community''s conditions.","keywords":[],"profile":"use-of-knowledge"}},{"id":"FNH-SPARK-P2-ORIGINAL-01-Q2::a","maxMarks":2,"sourcePartId":"FNH-SPARK-P2-ORIGINAL-01-Q2::a","kind":"structured","acceptedPhrases":[],"sourceFormat":"fnh-paper2","sourceMarking":{"modelPoints":["Carbohydrates.","Proteins.","Fats or lipids."],"explanation":"Award one mark for each different correct macronutrient, up to two.","keywords":["carbohydrate|starch|sugar","protein|fat|lipid"],"profile":"knowledge"}},{"id":"FNH-SPARK-P2-ORIGINAL-01-Q2::b","maxMarks":4,"sourcePartId":"FNH-SPARK-P2-ORIGINAL-01-Q2::b","kind":"structured","acceptedPhrases":[],"sourceFormat":"fnh-paper2","sourceMarking":{"modelPoints":["Iron: red meat, fish, fortified cereals, beans or dark leafy greens.","Vitamin C: guava, sweet pepper, citrus fruit or fresh fruit.","Calcium: dairy, fortified plant drink, small edible-bone fish or calcium-set tofu.","Award distinct accurate food–nutrient pairs, not foods without the linked nutrient."],"explanation":"A response such as ''callaloo is a plant iron source'' counts if the nutrient and food match.","keywords":[],"profile":"knowledge"}},{"id":"FNH-SPARK-P2-ORIGINAL-01-Q2::c","maxMarks":4,"sourcePartId":"FNH-SPARK-P2-ORIGINAL-01-Q2::c","kind":"structured","acceptedPhrases":[],"sourceFormat":"fnh-paper2","sourceMarking":{"modelPoints":["Fruit contributes vitamin C and fibre instead of relying on sweetened drinks.","Water supplies fluid without added sugar.","Iron-rich food supports haemoglobin formation and helps reduce deficiency risk.","Vitamin C at the same meal can improve absorption of non-haem iron from plant foods."],"explanation":"Award marks for two benefits each paired with correct explanations.","keywords":[],"profile":"use-of-knowledge"}},{"id":"FNH-SPARK-P2-ORIGINAL-01-Q2::d","maxMarks":6,"sourcePartId":"FNH-SPARK-P2-ORIGINAL-01-Q2::d","kind":"structured","acceptedPhrases":[],"sourceFormat":"fnh-paper2","sourceMarking":{"modelPoints":["Chewing and saliva begin mechanical digestion and starch breakdown in the mouth.","The stomach churns food and proteases assist protein digestion.","Pancreatic or intestinal amylase continues carbohydrate digestion in the small intestine.","Lipase digests fats; bile emulsifies fats but is not an enzyme.","Digested nutrients are absorbed mainly in the small intestine through villi.","Nutrients move into circulation for body use; undigested residue travels onward."],"explanation":"Six scientifically correct linked stages/roles; do not award a mark for describing bile as an enzyme.","keywords":[],"profile":"use-of-knowledge"}},{"id":"FNH-SPARK-P2-ORIGINAL-01-Q3::a","maxMarks":2,"sourcePartId":"FNH-SPARK-P2-ORIGINAL-01-Q3::a","kind":"structured","acceptedPhrases":[],"sourceFormat":"fnh-paper2","sourceMarking":{"modelPoints":["A four-mix combines foods selected from four food groups.","Food groups are chosen to provide a variety of nutrients, not simply four portions of one food."],"explanation":"Award the group count and the correct principle.","keywords":["four|4","groups|different"],"profile":"knowledge"}},{"id":"FNH-SPARK-P2-ORIGINAL-01-Q3::b","maxMarks":4,"sourcePartId":"FNH-SPARK-P2-ORIGINAL-01-Q3::b","kind":"structured","acceptedPhrases":[],"sourceFormat":"fnh-paper2","sourceMarking":{"modelPoints":["Budget and number of people to feed.","Vegetarian dietary pattern and other restrictions/allergies.","Nutrition and food-group balance.","Food safety and safe storage temperature.","Time, transport and available preparation equipment.","Colour, variety, taste and portion size."],"explanation":"One mark for each distinct relevant factor.","keywords":[],"profile":"knowledge"}},{"id":"FNH-SPARK-P2-ORIGINAL-01-Q3::c","maxMarks":4,"sourcePartId":"FNH-SPARK-P2-ORIGINAL-01-Q3::c","kind":"structured","acceptedPhrases":[],"sourceFormat":"fnh-paper2","sourceMarking":{"modelPoints":["Provide a suitable staple such as rice and a protein source such as peas or egg depending on vegetarian type.","Include vegetables such as pumpkin or cabbage and fruit.","State the relevant groups correctly.","Give two nutrient or safety-based justifications, such as protein, fibre, vitamins or safe chilling."],"explanation":"Award relevant foods, correct grouping and valid explanations.","keywords":[],"profile":"use-of-knowledge"}},{"id":"FNH-SPARK-P2-ORIGINAL-01-Q3::d","maxMarks":6,"sourcePartId":"FNH-SPARK-P2-ORIGINAL-01-Q3::d","kind":"structured","acceptedPhrases":[],"sourceFormat":"fnh-paper2","sourceMarking":{"modelPoints":["Create quantities and an estimated budget no higher than J$2,500.","Use available ingredients and compare prices or minimise waste.","Wash hands and clean preparation surfaces.","Separate raw and cooked/ready-to-eat foods.","Cook ingredients fully and maintain safe hot/cold conditions.","Pack in clean suitable containers and transport safely."],"explanation":"A sound sequence and cost justification is required; do not reward unrealistic unsafe storage.","keywords":[],"profile":"use-of-knowledge"}},{"id":"FNH-SPARK-P2-ORIGINAL-01-Q4::a","maxMarks":2,"sourcePartId":"FNH-SPARK-P2-ORIGINAL-01-Q4::a","kind":"structured","acceptedPhrases":[],"sourceFormat":"fnh-paper2","sourceMarking":{"modelPoints":["Spoilage is a deterioration in food quality that can make food unacceptable.","Contamination is the presence of harmful biological, chemical or physical substances; unsafe food may look normal."],"explanation":"Both concepts must be correctly separated.","keywords":["spoil|deteriorat","contaminat|harmful"],"profile":"knowledge"}},{"id":"FNH-SPARK-P2-ORIGINAL-01-Q4::b","maxMarks":4,"sourcePartId":"FNH-SPARK-P2-ORIGINAL-01-Q4::b","kind":"structured","acceptedPhrases":[],"sourceFormat":"fnh-paper2","sourceMarking":{"modelPoints":["Refrigeration or freezing.","Drying to reduce available moisture.","Properly controlled canning or heat processing.","Salting, sugaring, pickling or fermentation.","Suitable safe packaging and hygienic storage."],"explanation":"One mark for each valid method, with no duplicate descriptions.","keywords":[],"profile":"knowledge"}},{"id":"FNH-SPARK-P2-ORIGINAL-01-Q4::c","maxMarks":4,"sourcePartId":"FNH-SPARK-P2-ORIGINAL-01-Q4::c","kind":"structured","acceptedPhrases":[],"sourceFormat":"fnh-paper2","sourceMarking":{"modelPoints":["Unsafe holding allows growth of microorganisms and possible toxin formation; reheating may not remove every hazard.","Cool and refrigerate perishable filling promptly.","Keep raw ingredients and ready-to-eat foods separate; wash hands and sanitise utensils.","Use correct cooking, holding and refrigeration procedures."],"explanation":"Credit the hazard explanation plus two coherent preventive controls.","keywords":[],"profile":"use-of-knowledge"}},{"id":"FNH-SPARK-P2-ORIGINAL-01-Q4::d","maxMarks":6,"sourcePartId":"FNH-SPARK-P2-ORIGINAL-01-Q4::d","kind":"structured","acceptedPhrases":[],"sourceFormat":"fnh-paper2","sourceMarking":{"modelPoints":["Steaming mainly transfers heat from water vapour by convection and condensation.","Baking uses hot-air convection, radiation and conduction into the dough.","Steaming briefly with little water can help conserve some vitamins.","Yeast ferments available sugars and releases carbon dioxide that raises dough.","Correct yeast temperature/time and suitable mixing support proper rise.","Suitable oven heat and doneness checks prevent undercooking or burning."],"explanation":"Use accurate science and food outcomes rather than memorised cooking labels.","keywords":[],"profile":"use-of-knowledge"}},{"id":"FNH-SPARK-P2-ORIGINAL-01-Q5::a","maxMarks":2,"sourcePartId":"FNH-SPARK-P2-ORIGINAL-01-Q5::a","kind":"structured","acceptedPhrases":[],"sourceFormat":"fnh-paper2","sourceMarking":{"modelPoints":["Suitable work zones and clear paths between storage, washing and cooking areas.","Good lighting, ventilation, safe equipment placement and access to clean water."],"explanation":"Award two distinct safe layout features.","keywords":[],"profile":"knowledge"}},{"id":"FNH-SPARK-P2-ORIGINAL-01-Q5::b","maxMarks":4,"sourcePartId":"FNH-SPARK-P2-ORIGINAL-01-Q5::b","kind":"structured","acceptedPhrases":[],"sourceFormat":"fnh-paper2","sourceMarking":{"modelPoints":["Read and follow the instructions.","Check the cord and do not use damaged appliances.","Unplug before cleaning and keep motor parts dry.","Keep fingers and utensils away from moving blades.","Do not defeat safety locks or overload the appliance.","Store dry and maintain blades/attachments safely."],"explanation":"Award four sensible independent rules.","keywords":[],"profile":"knowledge"}},{"id":"FNH-SPARK-P2-ORIGINAL-01-Q5::c","maxMarks":4,"sourcePartId":"FNH-SPARK-P2-ORIGINAL-01-Q5::c","kind":"structured","acceptedPhrases":[],"sourceFormat":"fnh-paper2","sourceMarking":{"modelPoints":["Galley: two parallel work runs; efficient but potentially narrow/crowded.","L-shaped: two adjoining counters; open access but depends on available wall space.","Consider space, number of people, equipment and safe movement.","Select one layout and justify using actual household constraints."],"explanation":"The chosen layout may differ if well supported.","keywords":[],"profile":"use-of-knowledge"}},{"id":"FNH-SPARK-P2-ORIGINAL-01-Q5::d","maxMarks":6,"sourcePartId":"FNH-SPARK-P2-ORIGINAL-01-Q5::d","kind":"structured","acceptedPhrases":[],"sourceFormat":"fnh-paper2","sourceMarking":{"modelPoints":["Check basic appliance safety, quality and size needed.","Compare total price, warranty, repairability or running costs.","Check supplier reliability, label/manual and receipt.","Prepare a food budget and compare cost per edible portion.","Choose balanced seasonal ingredients appropriate for six people.","Explain safe storage, preparation and energy-saving actions."],"explanation":"Reward practical decisions based on evidence, not the size of a discount alone.","keywords":[],"profile":"use-of-knowledge"}},{"id":"FNH-SPARK-P2-ORIGINAL-01-Q6::a","maxMarks":2,"sourcePartId":"FNH-SPARK-P2-ORIGINAL-01-Q6::a","kind":"structured","acceptedPhrases":[],"sourceFormat":"fnh-paper2","sourceMarking":{"modelPoints":["Fortification means adding nutrients to a food to improve nutritional value or help prevent a deficiency.","An acceptable example is iodised salt, iron-fortified flour or vitamin-D-fortified milk."],"explanation":"One mark for the meaning and one for a genuine example.","keywords":["add|fortif","salt|flour|milk"],"profile":"knowledge"}},{"id":"FNH-SPARK-P2-ORIGINAL-01-Q6::b","maxMarks":4,"sourcePartId":"FNH-SPARK-P2-ORIGINAL-01-Q6::b","kind":"structured","acceptedPhrases":[],"sourceFormat":"fnh-paper2","sourceMarking":{"modelPoints":["Appearance and presentation.","Flavour or aroma.","Texture or consistency.","Safe and suitable serving temperature.","Portion size or nutritional suitability.","Food safety and hygiene."],"explanation":"Award four distinct relevant criteria.","keywords":[],"profile":"knowledge"}},{"id":"FNH-SPARK-P2-ORIGINAL-01-Q6::c","maxMarks":4,"sourcePartId":"FNH-SPARK-P2-ORIGINAL-01-Q6::c","kind":"structured","acceptedPhrases":[],"sourceFormat":"fnh-paper2","sourceMarking":{"modelPoints":["Calculation uses 250 ÷ 100 = 2.5 servings of 100 mL.","Sugar = 2.5 × 6 g = 15 g.","State the answer clearly with correct units.","Reduce added sugar through reformulation or offer unsweetened alternatives such as safe water."],"explanation":"Award method, calculation, unit and suitable improvement.","keywords":["2.5","15|15g","g|gram","water|less sugar|unsweetened"],"profile":"use-of-knowledge"}},{"id":"FNH-SPARK-P2-ORIGINAL-01-Q6::d","maxMarks":6,"sourcePartId":"FNH-SPARK-P2-ORIGINAL-01-Q6::d","kind":"structured","acceptedPhrases":[],"sourceFormat":"fnh-paper2","sourceMarking":{"modelPoints":["Maintain hand hygiene and separate raw fish from prepared foods.","Cook fish appropriately and handle hot soup safely.","Serve attractive portions with appropriate garnishes and dishware.","Keep the fruit drink prepared hygienically and cold until service.","Evaluate flavour, temperature, texture, appearance and portion against a checklist.","Describe a correct Caribbean cultural influence such as African, Indigenous, Indian or European contributions with a real dish example."],"explanation":"Credit practical sequencing, safety and an accurate cultural explanation.","keywords":[],"profile":"use-of-knowledge"}}]'::jsonb,false,'draft')
on conflict(subject_id,rubric_version,paper_id) do nothing;
insert into spark_grading_private.rubrics_v2(subject_id,rubric_version,paper_id,criteria,active,verification_status)
values ('food-nutrition-and-health','source-scheme-draft-v2','practice-02','[{"id":"FNH-SPARK-P2-ORIGINAL-02-Q1::a","maxMarks":2,"sourcePartId":"FNH-SPARK-P2-ORIGINAL-02-Q1::a","kind":"structured","acceptedPhrases":[],"sourceFormat":"fnh-paper2","sourceMarking":{"modelPoints":["A balanced diet provides adequate energy and essential nutrients in appropriate amounts.","Good health includes physical, mental and social wellbeing, not simply the absence of disease."],"explanation":"A balanced diet meets differing needs with variety and suitable portions while supporting overall health.","keywords":[],"profile":"knowledge"}},{"id":"FNH-SPARK-P2-ORIGINAL-02-Q1::b","maxMarks":4,"sourcePartId":"FNH-SPARK-P2-ORIGINAL-02-Q1::b","kind":"structured","acceptedPhrases":[],"sourceFormat":"fnh-paper2","sourceMarking":{"modelPoints":["Growth and age change energy and micronutrient needs.","Pregnancy and breastfeeding affect nutritional requirements.","Physical activity influences energy and fluid needs.","Illness or medication may affect nutrient requirements.","Personal allergies or intolerances influence food choices.","Reduced appetite, mobility or chewing difficulty can affect intake."],"explanation":"Any four distinct relevant factors earn credit; needs should be individually assessed.","keywords":[],"profile":"knowledge"}},{"id":"FNH-SPARK-P2-ORIGINAL-02-Q1::c","maxMarks":4,"sourcePartId":"FNH-SPARK-P2-ORIGINAL-02-Q1::c","kind":"structured","acceptedPhrases":[],"sourceFormat":"fnh-paper2","sourceMarking":{"modelPoints":["Growing adolescents require adequate energy and protein for growth and activity.","Iron needs may rise with growth and menstruation in some adolescents.","Older adults may require nutrient-dense meals because energy needs or appetite decline.","Chewing/swallowing difficulty may require food texture adjustments without removing nutrient variety."],"explanation":"Compare needs and reasons, rather than suggesting everyone within an age group must eat identical meals.","keywords":[],"profile":"use-of-knowledge"}},{"id":"FNH-SPARK-P2-ORIGINAL-02-Q1::d","maxMarks":6,"sourcePartId":"FNH-SPARK-P2-ORIGINAL-02-Q1::d","kind":"structured","acceptedPhrases":[],"sourceFormat":"fnh-paper2","sourceMarking":{"modelPoints":["State the chosen group and a specific nutritional priority.","Include an affordable staple such as oats, yam, breadfruit or rice.","Include a protein-rich option such as peas, eggs or fish as appropriate.","Include vegetables and fruit for fibre and vitamins.","Include safe drinking water and suitable portion planning.","Explain how preparation, food safety and budget suit the group."],"explanation":"A full answer links a feasible breakfast, lunch and dinner to the group''s needs and justifies the ingredients.","keywords":[],"profile":"use-of-knowledge"}},{"id":"FNH-SPARK-P2-ORIGINAL-02-Q2::a","maxMarks":2,"sourcePartId":"FNH-SPARK-P2-ORIGINAL-02-Q2::a","kind":"structured","acceptedPhrases":[],"sourceFormat":"fnh-paper2","sourceMarking":{"modelPoints":["Macronutrients are required in relatively large amounts, such as protein, carbohydrate or fat.","Micronutrients are needed in smaller amounts, including vitamins and minerals such as iron or vitamin C."],"explanation":"Macronutrients and micronutrients differ by required amount, not by whether they are important.","keywords":[],"profile":"knowledge"}},{"id":"FNH-SPARK-P2-ORIGINAL-02-Q2::b","maxMarks":4,"sourcePartId":"FNH-SPARK-P2-ORIGINAL-02-Q2::b","kind":"structured","acceptedPhrases":[],"sourceFormat":"fnh-paper2","sourceMarking":{"modelPoints":["Iron from peas or callaloo helps form haemoglobin.","Vitamin C from orange supports collagen formation and improves plant iron absorption.","Protein from fish or peas supplies amino acids for growth and tissue repair.","Carbohydrate from peas or pumpkin contributes energy.","Vitamin A precursors in pumpkin support normal vision.","Dietary fibre in vegetables and legumes supports bowel function."],"explanation":"Award one mark per valid nutrient-function pair, up to four distinct pairs.","keywords":[],"profile":"knowledge"}},{"id":"FNH-SPARK-P2-ORIGINAL-02-Q2::c","maxMarks":4,"sourcePartId":"FNH-SPARK-P2-ORIGINAL-02-Q2::c","kind":"structured","acceptedPhrases":[],"sourceFormat":"fnh-paper2","sourceMarking":{"modelPoints":["Vitamin C improves non-haem iron absorption from peas and leafy vegetables.","Orange provides vitamins, fluid and some dietary fibre.","Prolonged cooking in water can reduce some water-soluble vitamins.","Cutting and exposing produce to air and heat for long periods can reduce some nutrients."],"explanation":"Look for a physiological benefit and a genuine storage or cooking factor; avoid claims that fruit cures deficiencies.","keywords":[],"profile":"use-of-knowledge"}},{"id":"FNH-SPARK-P2-ORIGINAL-02-Q2::d","maxMarks":6,"sourcePartId":"FNH-SPARK-P2-ORIGINAL-02-Q2::d","kind":"structured","acceptedPhrases":[],"sourceFormat":"fnh-paper2","sourceMarking":{"modelPoints":["Chewing mixes food with saliva and starts mechanical digestion.","Amylases break starch into smaller carbohydrates.","Proteases in the stomach and small intestine break protein into smaller peptides and amino acids.","Bile emulsifies fats and provides more surface for lipase; bile itself is not an enzyme.","Lipase helps break down fats into smaller absorbable components.","Most digested nutrients are absorbed through the small intestine''s lining and villi."],"explanation":"Six correctly connected stages and functions make a full explanation; naming an organ alone is insufficient.","keywords":[],"profile":"use-of-knowledge"}},{"id":"FNH-SPARK-P2-ORIGINAL-02-Q3::a","maxMarks":2,"sourcePartId":"FNH-SPARK-P2-ORIGINAL-02-Q3::a","kind":"structured","acceptedPhrases":[],"sourceFormat":"fnh-paper2","sourceMarking":{"modelPoints":["A multi-mix combines foods from more than one food group to increase dietary variety.","A four-mix contains four different food groups, not simply four servings of one ingredient."],"explanation":"The multi-mix approach considers food groups and nutritional variety, not only the number of dishes.","keywords":[],"profile":"knowledge"}},{"id":"FNH-SPARK-P2-ORIGINAL-02-Q3::b","maxMarks":4,"sourcePartId":"FNH-SPARK-P2-ORIGINAL-02-Q3::b","kind":"structured","acceptedPhrases":[],"sourceFormat":"fnh-paper2","sourceMarking":{"modelPoints":["Available budget and cost per edible portion.","Number of diners and suitable food quantities.","Vegetarian pattern and any allergy restrictions.","Adequate nutrient balance and appropriate portions.","Food-safety requirements during cooling, packing and transport.","Preparation time, equipment, fuel and food availability."],"explanation":"Accept four distinct relevant considerations, not repeated points about price.","keywords":[],"profile":"knowledge"}},{"id":"FNH-SPARK-P2-ORIGINAL-02-Q3::c","maxMarks":4,"sourcePartId":"FNH-SPARK-P2-ORIGINAL-02-Q3::c","kind":"structured","acceptedPhrases":[],"sourceFormat":"fnh-paper2","sourceMarking":{"modelPoints":["The 1.5 kg pack costs J$840 ÷ 1.5 = J$560 per kg.","The 500 g pack costs J$310 ÷ 0.5 = J$620 per kg.","The 1.5 kg pack has the lower unit price.","Saving per kilogram is J$620 - J$560 = J$60."],"explanation":"State both unit prices, select the cheaper per-kilogram option and calculate the J$60 saving correctly.","keywords":[],"profile":"use-of-knowledge"}},{"id":"FNH-SPARK-P2-ORIGINAL-02-Q3::d","maxMarks":6,"sourcePartId":"FNH-SPARK-P2-ORIGINAL-02-Q3::d","kind":"structured","acceptedPhrases":[],"sourceFormat":"fnh-paper2","sourceMarking":{"modelPoints":["Scale ingredients and portion sizes for 12 balanced vegetarian lunches.","Use rice and peas for energy, plant protein and fibre.","Include cabbage/carrots and pawpaw for a wider range of vitamins and fibre.","Wash hands and vegetables and use clean equipment.","Cook foods thoroughly and prevent raw-to-ready-to-eat cross-contamination.","Cool and hold perishable meals safely, using suitable covered containers and time-temperature controls."],"explanation":"Award marks for planning, nutrition, hygiene and safe transport linked to the case.","keywords":[],"profile":"use-of-knowledge"}},{"id":"FNH-SPARK-P2-ORIGINAL-02-Q4::a","maxMarks":2,"sourcePartId":"FNH-SPARK-P2-ORIGINAL-02-Q4::a","kind":"structured","acceptedPhrases":[],"sourceFormat":"fnh-paper2","sourceMarking":{"modelPoints":["Contamination is the presence of an unwanted biological, chemical or physical hazard in food.","Spoilage is deterioration in food quality; contaminated food may have no obvious signs of spoilage."],"explanation":"Hazard and visible quality change are different ideas; a pleasant smell does not prove food is safe.","keywords":[],"profile":"knowledge"}},{"id":"FNH-SPARK-P2-ORIGINAL-02-Q4::b","maxMarks":4,"sourcePartId":"FNH-SPARK-P2-ORIGINAL-02-Q4::b","kind":"structured","acceptedPhrases":[],"sourceFormat":"fnh-paper2","sourceMarking":{"modelPoints":["Suitable refrigeration or freezing slows microbial growth.","Drying reduces available water for microbial growth.","Correctly controlled pasteurisation uses heat to reduce selected microbes.","Safe acidification/pickling can inhibit selected organisms.","Validated canning uses suitable heat and sealed containers for shelf stability.","Suitable packaging and hygienic storage prevent recontamination."],"explanation":"A preservation method must be paired with correct safe controls; home canning needs validated processing.","keywords":[],"profile":"knowledge"}},{"id":"FNH-SPARK-P2-ORIGINAL-02-Q4::c","maxMarks":4,"sourcePartId":"FNH-SPARK-P2-ORIGINAL-02-Q4::c","kind":"structured","acceptedPhrases":[],"sourceFormat":"fnh-paper2","sourceMarking":{"modelPoints":["Raw meat liquids can drip or splash onto ready-to-eat sauce.","Handling raw meat and sauce with unwashed hands or shared utensils transfers microbes.","Store cooked sauce covered and separate from raw meats.","Wash hands and sanitise food-contact tools before handling ready-to-eat foods."],"explanation":"Link the contamination pathways to controls instead of listing unrelated cleaning habits.","keywords":[],"profile":"use-of-knowledge"}},{"id":"FNH-SPARK-P2-ORIGINAL-02-Q4::d","maxMarks":6,"sourcePartId":"FNH-SPARK-P2-ORIGINAL-02-Q4::d","kind":"structured","acceptedPhrases":[],"sourceFormat":"fnh-paper2","sourceMarking":{"modelPoints":["Conduction transfers heat through direct contact between a pan and food.","Convection transfers heat through moving hot liquid or air.","Radiation transfers heat through electromagnetic waves, such as from a grill element.","Starch gelatinisation thickens a mixture when hydrated starch is heated.","Protein denaturation or coagulation changes texture during cooking.","Use validated cooking, rapid appropriate cooling, clean packaging and safe storage to limit hazards."],"explanation":"Award six applied scientific or safety points; do not present heating as a cure for all contamination.","keywords":[],"profile":"use-of-knowledge"}},{"id":"FNH-SPARK-P2-ORIGINAL-02-Q5::a","maxMarks":2,"sourcePartId":"FNH-SPARK-P2-ORIGINAL-02-Q5::a","kind":"structured","acceptedPhrases":[],"sourceFormat":"fnh-paper2","sourceMarking":{"modelPoints":["Available floor space, safe clearances and household needs determine layout.","Work zones, traffic flow, ventilation, lighting and access to water/electricity affect safety."],"explanation":"Kitchen design must suit actual equipment, workers and safe movement.","keywords":[],"profile":"knowledge"}},{"id":"FNH-SPARK-P2-ORIGINAL-02-Q5::b","maxMarks":4,"sourcePartId":"FNH-SPARK-P2-ORIGINAL-02-Q5::b","kind":"structured","acceptedPhrases":[],"sourceFormat":"fnh-paper2","sourceMarking":{"modelPoints":["Read operating and cleaning instructions before use.","Inspect cords, plugs and safety guards for damage.","Unplug small electrical appliances before suitable cleaning.","Keep the motor or electrical housing away from water.","Avoid overloading and never bypass interlocks.","Ask a qualified person to assess defective electrical equipment."],"explanation":"Distinct practices earn credit. Users should not attempt unsafe electrical repairs.","keywords":[],"profile":"knowledge"}},{"id":"FNH-SPARK-P2-ORIGINAL-02-Q5::c","maxMarks":4,"sourcePartId":"FNH-SPARK-P2-ORIGINAL-02-Q5::c","kind":"structured","acceptedPhrases":[],"sourceFormat":"fnh-paper2","sourceMarking":{"modelPoints":["Three work runs can provide considerable counter and storage space.","Connected work zones may reduce movement between preparing, washing and cooking.","Insufficient aisle clearance can cause congestion.","Corners can be difficult to access and require planning.","It may cost more or need more room than a single-wall layout.","Crowded appliance door openings can create injury risks."],"explanation":"Credit two advantages and two disadvantages connected to the school''s space and workflow.","keywords":[],"profile":"use-of-knowledge"}},{"id":"FNH-SPARK-P2-ORIGINAL-02-Q5::d","maxMarks":6,"sourcePartId":"FNH-SPARK-P2-ORIGINAL-02-Q5::d","kind":"structured","acceptedPhrases":[],"sourceFormat":"fnh-paper2","sourceMarking":{"modelPoints":["Compare appliance safety features and compliance with applicable standards.","Check capacity and suitability for school batch sizes.","Compare total cost, durability, warranty and running expenses.","Keep receipts and reliable supplier details for consumer protection.","Organise mise en place and shared preparation schedules to save time.","Clean and maintain equipment safely, conserve energy and keep work areas dry."],"explanation":"Credit financial reasoning, consumer rights and daily kitchen efficiency rather than a vague recommendation to buy the cheapest appliance.","keywords":[],"profile":"use-of-knowledge"}},{"id":"FNH-SPARK-P2-ORIGINAL-02-Q6::a","maxMarks":2,"sourcePartId":"FNH-SPARK-P2-ORIGINAL-02-Q6::a","kind":"structured","acceptedPhrases":[],"sourceFormat":"fnh-paper2","sourceMarking":{"modelPoints":["Boiling, steaming, simmering or poaching are moist-heat methods.","Frying cooks through hot fat or oil, unlike heating with water or steam."],"explanation":"Give two valid moist-heat examples and correctly distinguish their heating medium.","keywords":[],"profile":"knowledge"}},{"id":"FNH-SPARK-P2-ORIGINAL-02-Q6::b","maxMarks":4,"sourcePartId":"FNH-SPARK-P2-ORIGINAL-02-Q6::b","kind":"structured","acceptedPhrases":[],"sourceFormat":"fnh-paper2","sourceMarking":{"modelPoints":["Food safety, hygiene and suitable serving temperature.","Appearance, plate arrangement and safe garnish.","Taste or aroma appropriate to the recipe.","Texture and consistency.","Suitable portion size and nutritional appropriateness.","Reasonable food cost and adherence to the task brief."],"explanation":"Award four distinct measurable quality criteria, including at least one food-safety factor.","keywords":[],"profile":"knowledge"}},{"id":"FNH-SPARK-P2-ORIGINAL-02-Q6::c","maxMarks":4,"sourcePartId":"FNH-SPARK-P2-ORIGINAL-02-Q6::c","kind":"structured","acceptedPhrases":[],"sourceFormat":"fnh-paper2","sourceMarking":{"modelPoints":["300 ÷ 100 = 3 reference portions.","3 × 7 g = 21 g sugar per drink.","Reduce added sugar or serve a lower-sugar reformulation.","Offer safe plain water and suitable unsweetened options, while maintaining hygienic handling."],"explanation":"Show units and calculation; suggestions should be realistic rather than claiming all fruit sugars are identical to added sugar.","keywords":[],"profile":"use-of-knowledge"}},{"id":"FNH-SPARK-P2-ORIGINAL-02-Q6::d","maxMarks":6,"sourcePartId":"FNH-SPARK-P2-ORIGINAL-02-Q6::d","kind":"structured","acceptedPhrases":[],"sourceFormat":"fnh-paper2","sourceMarking":{"modelPoints":["Write a logical timeline and allocate tools and workstations.","Separate raw fish from ready-to-eat vegetables and wash hands properly.","Cook fish appropriately and hold hot and cold foods safely.","Present balanced portions with clean dishes and edible garnishes.","Use an agreed sensory and hygiene rubric to collect evidence and propose improvements.","Explain a correctly sourced cultural influence, such as Indian roti traditions, African one-pot cooking, or Indigenous cassava techniques in Caribbean foods."],"explanation":"A full response integrates safety, food quality, practical management and respect for Caribbean culinary history.","keywords":[],"profile":"use-of-knowledge"}}]'::jsonb,false,'draft')
on conflict(subject_id,rubric_version,paper_id) do nothing;
insert into spark_grading_private.rubrics_v2(subject_id,rubric_version,paper_id,criteria,active,verification_status)
values ('principles-of-business','source-scheme-draft-v2','pob-original-paper2-01','[{"id":"POB-SPARK-P2-ORIGINAL-01-Q1::a","maxMarks":2,"sourcePartId":"POB-SPARK-P2-ORIGINAL-01-Q1::a","kind":"structured","acceptedPhrases":[],"sourceFormat":"pob-paper2","sourceMarking":{"criteria":[{"marks":2,"rule":"A person who identifies an opportunity, organises resources and accepts business risks.","alternatives":["business organiser taking risk","person starting and operating a business"]}],"modelAnswer":"An entrepreneur organises production and bears risk."}},{"id":"POB-SPARK-P2-ORIGINAL-01-Q1::b","maxMarks":3,"sourcePartId":"POB-SPARK-P2-ORIGINAL-01-Q1::b","kind":"structured","acceptedPhrases":[],"sourceFormat":"pob-paper2","sourceMarking":{"criteria":[{"marks":1,"rule":"Evidence of likely demand and competition.","alternatives":[]},{"marks":1,"rule":"Realistic costs and access to finance.","alternatives":[]},{"marks":1,"rule":"Health, registration, supplier or legal requirements.","alternatives":[]}],"modelAnswer":"They should study demand, start-up costs and the regulatory requirements."}},{"id":"POB-SPARK-P2-ORIGINAL-01-Q1::c","maxMarks":4,"sourcePartId":"POB-SPARK-P2-ORIGINAL-01-Q1::c","kind":"structured","acceptedPhrases":[],"sourceFormat":"pob-paper2","sourceMarking":{"criteria":[{"marks":1,"rule":"Pooling finance and skills.","alternatives":[]},{"marks":1,"rule":"Sharing work, responsibilities and decisions.","alternatives":[]},{"marks":1,"rule":"Potential disagreement or slower decisions.","alternatives":[]},{"marks":1,"rule":"Possible personal liability or difficult ownership continuity, depending on legal form.","alternatives":[]}],"modelAnswer":"Partners can pool money and expertise, but decisions may cause disputes and liability must be understood."}},{"id":"POB-SPARK-P2-ORIGINAL-01-Q1::d","maxMarks":4,"sourcePartId":"POB-SPARK-P2-ORIGINAL-01-Q1::d","kind":"structured","acceptedPhrases":[],"sourceFormat":"pob-paper2","sourceMarking":{"criteria":[{"marks":2,"rule":"A plan estimates demand and operating costs and shows whether the idea could be viable.","alternatives":[]},{"marks":2,"rule":"A plan sets out the team, repayment approach and risks for lenders or investors.","alternatives":[]}],"modelAnswer":"A plan helps the owners assess cash requirements and presents evidence to prospective lenders."}},{"id":"POB-SPARK-P2-ORIGINAL-01-Q1::e","maxMarks":7,"sourcePartId":"POB-SPARK-P2-ORIGINAL-01-Q1::e","kind":"structured","acceptedPhrases":[],"sourceFormat":"pob-paper2","sourceMarking":{"criteria":[{"marks":1,"rule":"Names a legally plausible business structure.","alternatives":[]},{"marks":2,"rule":"Explains liability and ownership implications.","alternatives":[]},{"marks":2,"rule":"Explains the effect on access to finance or management.","alternatives":[]},{"marks":2,"rule":"Connects the choice to this sauce business''s scale, partners and expansion plans.","alternatives":[]}],"modelAnswer":"A registered company may suit a growing venture seeking separation of personal and business obligations, but a partnership may be cheaper initially. Credit any well-justified alternative."}},{"id":"POB-SPARK-P2-ORIGINAL-01-Q2::a","maxMarks":2,"sourcePartId":"POB-SPARK-P2-ORIGINAL-01-Q2::a","kind":"structured","acceptedPhrases":[],"sourceFormat":"pob-paper2","sourceMarking":{"criteria":[{"marks":1,"rule":"Any one valid management function: planning, organising, leading or controlling.","alternatives":[]},{"marks":1,"rule":"A second distinct valid management function.","alternatives":[]}],"modelAnswer":"Planning and organising are two management functions."}},{"id":"POB-SPARK-P2-ORIGINAL-01-Q2::b","maxMarks":3,"sourcePartId":"POB-SPARK-P2-ORIGINAL-01-Q2::b","kind":"structured","acceptedPhrases":[],"sourceFormat":"pob-paper2","sourceMarking":{"criteria":[{"marks":1,"rule":"Names and contact details of the parties.","alternatives":[]},{"marks":1,"rule":"Quantity and description of goods or services.","alternatives":[]},{"marks":1,"rule":"Agreed prices, reference details or delivery terms.","alternatives":[]}],"modelAnswer":"The order should identify parties, goods and prices and delivery instructions."}},{"id":"POB-SPARK-P2-ORIGINAL-01-Q2::c","maxMarks":4,"sourcePartId":"POB-SPARK-P2-ORIGINAL-01-Q2::c","kind":"structured","acceptedPhrases":[],"sourceFormat":"pob-paper2","sourceMarking":{"criteria":[{"marks":1,"rule":"Identifies unclear duties or conflicting instructions.","alternatives":[]},{"marks":1,"rule":"Offers role descriptions or a meeting to clarify responsibilities.","alternatives":[]},{"marks":1,"rule":"Identifies an additional genuine conflict cause, such as unfair workload.","alternatives":[]},{"marks":1,"rule":"Offers a fair resolution, such as negotiation or a grievance procedure.","alternatives":[]}],"modelAnswer":"Clear communication and fair conflict resolution can restore teamwork."}},{"id":"POB-SPARK-P2-ORIGINAL-01-Q2::d","maxMarks":5,"sourcePartId":"POB-SPARK-P2-ORIGINAL-01-Q2::d","kind":"structured","acceptedPhrases":[],"sourceFormat":"pob-paper2","sourceMarking":{"criteria":[{"marks":2,"rule":"Identifies an offer containing an agreed service, price and date.","alternatives":[]},{"marks":1,"rule":"Shows clear acceptance of the offer.","alternatives":[]},{"marks":2,"rule":"Identifies exchanged value, such as the agreed payment for catering services.","alternatives":[]}],"modelAnswer":"A priced catering quotation accepted by the customer may establish an enforceable agreement, provided other requirements are met."}},{"id":"POB-SPARK-P2-ORIGINAL-01-Q2::e","maxMarks":6,"sourcePartId":"POB-SPARK-P2-ORIGINAL-01-Q2::e","kind":"structured","acceptedPhrases":[],"sourceFormat":"pob-paper2","sourceMarking":{"criteria":[{"marks":2,"rule":"Communicate promptly with the customer and supplier and discuss an appropriate lawful remedy.","alternatives":[]},{"marks":2,"rule":"Review the delivery terms, evidence and documentation to establish obligations.","alternatives":[]},{"marks":2,"rule":"Create clearer schedules, supplier checks or backup arrangements to prevent recurrence.","alternatives":[]}],"modelAnswer":"The company should address the customer, document the breach and improve supplier controls."}},{"id":"POB-SPARK-P2-ORIGINAL-01-Q3::a","maxMarks":3,"sourcePartId":"POB-SPARK-P2-ORIGINAL-01-Q3::a","kind":"structured","acceptedPhrases":[],"sourceFormat":"pob-paper2","sourceMarking":{"criteria":[{"marks":1,"rule":"Defines labour productivity as output per unit of labour input.","alternatives":[]},{"marks":1,"rule":"Correctly divides 300 by 10.","alternatives":[]},{"marks":1,"rule":"States 30 bottles per labour hour with correct unit.","alternatives":[]}],"modelAnswer":"300 ÷ 10 = 30 bottles per labour hour."}},{"id":"POB-SPARK-P2-ORIGINAL-01-Q3::b","maxMarks":2,"sourcePartId":"POB-SPARK-P2-ORIGINAL-01-Q3::b","kind":"structured","acceptedPhrases":[],"sourceFormat":"pob-paper2","sourceMarking":{"criteria":[{"marks":1,"rule":"Any one valid element other than price: product, place or promotion.","alternatives":[]},{"marks":1,"rule":"A second distinct valid element other than price.","alternatives":[]}],"modelAnswer":"Product and promotion are two elements of the four Ps."}},{"id":"POB-SPARK-P2-ORIGINAL-01-Q3::c","maxMarks":4,"sourcePartId":"POB-SPARK-P2-ORIGINAL-01-Q3::c","kind":"structured","acceptedPhrases":[],"sourceFormat":"pob-paper2","sourceMarking":{"criteria":[{"marks":1,"rule":"Correctly identifies selling price as J$250.","alternatives":[]},{"marks":1,"rule":"Correctly identifies variable cost as J$130.","alternatives":[]},{"marks":1,"rule":"Calculates J$120 per bottle.","alternatives":[]},{"marks":1,"rule":"Explains contribution helps meet fixed costs before profit.","alternatives":[]}],"modelAnswer":"Contribution per bottle = J$250 - J$130 = J$120."}},{"id":"POB-SPARK-P2-ORIGINAL-01-Q3::d","maxMarks":4,"sourcePartId":"POB-SPARK-P2-ORIGINAL-01-Q3::d","kind":"structured","acceptedPhrases":[],"sourceFormat":"pob-paper2","sourceMarking":{"criteria":[{"marks":1,"rule":"An advantage such as spreading fixed costs or serving more customers.","alternatives":[]},{"marks":1,"rule":"A second distinct advantage such as better purchasing power.","alternatives":[]},{"marks":1,"rule":"A risk such as quality problems, cash shortages or extra management.","alternatives":[]},{"marks":1,"rule":"A second distinct risk connected to growth.","alternatives":[]}],"modelAnswer":"Growth may create economies of scale but can strain cash flow and quality."}},{"id":"POB-SPARK-P2-ORIGINAL-01-Q3::e","maxMarks":7,"sourcePartId":"POB-SPARK-P2-ORIGINAL-01-Q3::e","kind":"structured","acceptedPhrases":[],"sourceFormat":"pob-paper2","sourceMarking":{"criteria":[{"marks":1,"rule":"Defines a relevant target market.","alternatives":[]},{"marks":2,"rule":"Explains a suitable product or packaging decision.","alternatives":[]},{"marks":2,"rule":"Explains pricing based on costs and customer value.","alternatives":[]},{"marks":2,"rule":"Justifies suitable placement and truthful promotion methods.","alternatives":[]}],"modelAnswer":"For example, target commuters with clearly labelled convenient bottles, fair prices, safe retail placement and sample promotions."}},{"id":"POB-SPARK-P2-ORIGINAL-01-Q4::a","maxMarks":2,"sourcePartId":"POB-SPARK-P2-ORIGINAL-01-Q4::a","kind":"structured","acceptedPhrases":[],"sourceFormat":"pob-paper2","sourceMarking":{"criteria":[{"marks":2,"rule":"Planning, controlling and coordinating movement or storage of goods and related information.","alternatives":[]}],"modelAnswer":"Logistics manages transport, handling, storage and delivery."}},{"id":"POB-SPARK-P2-ORIGINAL-01-Q4::b","maxMarks":3,"sourcePartId":"POB-SPARK-P2-ORIGINAL-01-Q4::b","kind":"structured","acceptedPhrases":[],"sourceFormat":"pob-paper2","sourceMarking":{"criteria":[{"marks":1,"rule":"One relevant transport or delivery document.","alternatives":[]},{"marks":1,"rule":"A second different relevant transport or delivery document.","alternatives":[]},{"marks":1,"rule":"A third different relevant transport or delivery document.","alternatives":[]}],"modelAnswer":"The distributor should use correct shipping and delivery paperwork."}},{"id":"POB-SPARK-P2-ORIGINAL-01-Q4::c","maxMarks":4,"sourcePartId":"POB-SPARK-P2-ORIGINAL-01-Q4::c","kind":"structured","acceptedPhrases":[],"sourceFormat":"pob-paper2","sourceMarking":{"criteria":[{"marks":2,"rule":"Delays reduce product availability and may cause dissatisfied or lost customers.","alternatives":[]},{"marks":2,"rule":"Spoilage or damage increases waste, costs and potential claims.","alternatives":[]}],"modelAnswer":"Delayed or unsafe delivery affects sales, stock and reputation."}},{"id":"POB-SPARK-P2-ORIGINAL-01-Q4::d","maxMarks":5,"sourcePartId":"POB-SPARK-P2-ORIGINAL-01-Q4::d","kind":"structured","acceptedPhrases":[],"sourceFormat":"pob-paper2","sourceMarking":{"criteria":[{"marks":2,"rule":"Backup supplier or route plans with clear responsibilities.","alternatives":[]},{"marks":2,"rule":"Suitable temperature monitoring, packaging and cold-chain equipment.","alternatives":[]},{"marks":1,"rule":"Realistic forecasting, stock records or delivery tracking.","alternatives":[]}],"modelAnswer":"Maintain a cold chain, prepare contingency routes and track perishable shipments."}},{"id":"POB-SPARK-P2-ORIGINAL-01-Q4::e","maxMarks":6,"sourcePartId":"POB-SPARK-P2-ORIGINAL-01-Q4::e","kind":"structured","acceptedPhrases":[],"sourceFormat":"pob-paper2","sourceMarking":{"criteria":[{"marks":2,"rule":"Explains GPS and digital records for location and delivery tracking.","alternatives":[]},{"marks":2,"rule":"Explains inventory and temperature monitoring for avoiding shortages and spoilage.","alternatives":[]},{"marks":2,"rule":"Evaluates an implementation risk such as cost, security, connectivity or training.","alternatives":[]}],"modelAnswer":"ICT can improve visibility and customer service, but it needs reliable systems and proper controls."}},{"id":"POB-SPARK-P2-ORIGINAL-01-Q5::a","maxMarks":3,"sourcePartId":"POB-SPARK-P2-ORIGINAL-01-Q5::a","kind":"structured","acceptedPhrases":[],"sourceFormat":"pob-paper2","sourceMarking":{"criteria":[{"marks":1,"rule":"Identifies revenue J$850,000.","alternatives":[]},{"marks":1,"rule":"Identifies cost of sales J$470,000.","alternatives":[]},{"marks":1,"rule":"Subtracts correctly to obtain J$380,000.","alternatives":[]}],"modelAnswer":"Gross profit = J$850,000 - J$470,000 = J$380,000."}},{"id":"POB-SPARK-P2-ORIGINAL-01-Q5::b","maxMarks":3,"sourcePartId":"POB-SPARK-P2-ORIGINAL-01-Q5::b","kind":"structured","acceptedPhrases":[],"sourceFormat":"pob-paper2","sourceMarking":{"criteria":[{"marks":1,"rule":"Starts with gross profit J$380,000.","alternatives":[]},{"marks":1,"rule":"Deducts operating expenses J$260,000.","alternatives":[]},{"marks":1,"rule":"Obtains J$120,000 and labels it correctly.","alternatives":[]}],"modelAnswer":"Net profit = J$380,000 - J$260,000 = J$120,000."}},{"id":"POB-SPARK-P2-ORIGINAL-01-Q5::c","maxMarks":4,"sourcePartId":"POB-SPARK-P2-ORIGINAL-01-Q5::c","kind":"structured","acceptedPhrases":[],"sourceFormat":"pob-paper2","sourceMarking":{"criteria":[{"marks":1,"rule":"Saving prioritises holding funds for future use.","alternatives":[]},{"marks":1,"rule":"Investment uses funds to purchase an asset or opportunity for expected returns.","alternatives":[]},{"marks":1,"rule":"Example of liquid business savings.","alternatives":[]},{"marks":1,"rule":"Example of a productive investment such as new equipment.","alternatives":[]}],"modelAnswer":"Keeping an emergency bank balance is saving; buying production equipment is an investment."}},{"id":"POB-SPARK-P2-ORIGINAL-01-Q5::d","maxMarks":4,"sourcePartId":"POB-SPARK-P2-ORIGINAL-01-Q5::d","kind":"structured","acceptedPhrases":[],"sourceFormat":"pob-paper2","sourceMarking":{"criteria":[{"marks":2,"rule":"Exports can bring foreign-exchange earnings to the economy.","alternatives":[]},{"marks":2,"rule":"Business development can support local jobs, taxes, production or diversified markets.","alternatives":[]}],"modelAnswer":"Export growth may generate foreign exchange and additional economic opportunities."}},{"id":"POB-SPARK-P2-ORIGINAL-01-Q5::e","maxMarks":6,"sourcePartId":"POB-SPARK-P2-ORIGINAL-01-Q5::e","kind":"structured","acceptedPhrases":[],"sourceFormat":"pob-paper2","sourceMarking":{"criteria":[{"marks":2,"rule":"More accurate or faster stock monitoring and reordering.","alternatives":[]},{"marks":2,"rule":"Better tracking can reduce stockouts or waste and support decisions.","alternatives":[]},{"marks":2,"rule":"Discusses a meaningful risk and control, such as data loss with backups or costs and training.","alternatives":[]}],"modelAnswer":"A stock system can improve efficiency but must have backups, data protection and trained users."}}]'::jsonb,false,'draft')
